-- ----------------------------------------------------------------------------
-- OntologyAxioms: Positive-form invariants the project is built on. These are the load-bearing claims; if any one is dropped, the methodology no longer holds. FramingInvariants are mistakes that violate these axioms.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ontology_axioms (
  axiom_id                            TEXT                 PRIMARY KEY
);
ALTER TABLE ontology_axioms ADD COLUMN IF NOT EXISTS short_name TEXT;
ALTER TABLE ontology_axioms ADD COLUMN IF NOT EXISTS statement TEXT;                                -- The axiom in one sentence
ALTER TABLE ontology_axioms ADD COLUMN IF NOT EXISTS why TEXT;                                      -- What collapses if you give this up
ALTER TABLE ontology_axioms ADD COLUMN IF NOT EXISTS implication TEXT;                              -- Concrete consequence for how the project is built / discussed
ALTER TABLE ontology_axioms ADD COLUMN IF NOT EXISTS status TEXT;                                   -- active | revising | retired
COMMENT ON TABLE ontology_axioms IS 'Positive-form invariants the project is built on. These are the load-bearing claims; if any one is dropped, the methodology no longer holds. FramingInvariants are mistakes that violate these axioms.';
COMMENT ON COLUMN ontology_axioms.statement IS 'The axiom in one sentence';
COMMENT ON COLUMN ontology_axioms.why IS 'What collapses if you give this up';
COMMENT ON COLUMN ontology_axioms.implication IS 'Concrete consequence for how the project is built / discussed';
COMMENT ON COLUMN ontology_axioms.status IS 'active | revising | retired';

-- ----------------------------------------------------------------------------
-- FramingInvariants: Mistakes-to-avoid catalog. Each row is one wrong framing that has been caught and corrected, paired with the right framing and the axiom it violates. The portal surfaces these so future agents (and humans) can be re-grounded without rediscovering them.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS framing_invariants (
  invariant_id                        TEXT                 PRIMARY KEY
);
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS name TEXT;                                  -- Short title for grouping / display
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS category TEXT;                              -- substrate-equality | ssot-locality | hub-spoke-topology | category-error | fail-loud | role-confusion | naming | project-catalog | build-semantics | dialect-binding
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS wrong_framing TEXT;                         -- The mistake verbatim
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS correct_framing TEXT;                       -- The right framing
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS why TEXT;                                   -- The reasoning that anchors it
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS violated_axiom_id TEXT;                     -- FK to OntologyAxioms.AxiomId — which axiom the wrong framing violates
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS severity TEXT;                              -- critical | important | nuance
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS example_context TEXT;                       -- Where this came up — useful so future agents can recognise the situation
ALTER TABLE framing_invariants ADD COLUMN IF NOT EXISTS status TEXT;                                -- active | retired
COMMENT ON TABLE framing_invariants IS 'Mistakes-to-avoid catalog. Each row is one wrong framing that has been caught and corrected, paired with the right framing and the axiom it violates. The portal surfaces these so future agents (and humans) can be re-grounded without rediscovering them.';
COMMENT ON COLUMN framing_invariants.name IS 'Short title for grouping / display';
COMMENT ON COLUMN framing_invariants.category IS 'substrate-equality | ssot-locality | hub-spoke-topology | category-error | fail-loud | role-confusion | naming | project-catalog | build-semantics | dialect-binding';
COMMENT ON COLUMN framing_invariants.wrong_framing IS 'The mistake verbatim';
COMMENT ON COLUMN framing_invariants.correct_framing IS 'The right framing';
COMMENT ON COLUMN framing_invariants.why IS 'The reasoning that anchors it';
COMMENT ON COLUMN framing_invariants.violated_axiom_id IS 'FK to OntologyAxioms.AxiomId — which axiom the wrong framing violates';
COMMENT ON COLUMN framing_invariants.severity IS 'critical | important | nuance';
COMMENT ON COLUMN framing_invariants.example_context IS 'Where this came up — useful so future agents can recognise the situation';
COMMENT ON COLUMN framing_invariants.status IS 'active | retired';

-- ----------------------------------------------------------------------------
-- PlatformFeatures: The catalog of distinctive features the ERB platform offers. The rulebook is the formal SSoT for this list; the repo's README and per-feature README files MUST conform to these rows. Each feature has a one-line summary (the elevator pitch), a Tier (headline vs additional), a Priority (sort order within tier), and a ReadmeFilePath (where the long-form explanation lives — even if it's still a stub). IsReadmeStub is calculated so 'which READMEs are still missing' is a queryable fact, not a tribal one. Many features reference an OntologyAxiom — that's the axiom the feature operationalizes.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS platform_features (
  feature_id                          TEXT                 PRIMARY KEY          -- Stable PK, e.g. feature-001
);
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS name TEXT;                                   -- Full feature name as it appears in headings
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS short_name TEXT;                             -- Short identifier for cross-references (e.g. 'ADP', 'Hub-and-Spoke')
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS tier TEXT;                                   -- headline | additional — drives the two README sections
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS priority NUMERIC;                            -- Sort order within tier (lower = higher up)
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS one_line_summary TEXT;                       -- The elevator pitch — one sentence, no clauses about hypotheticals
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS readme_file_path TEXT;                       -- Path to the per-feature README, relative to repo root. Hand-maintained but MUST conform to this row.
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS readme_stub_content TEXT;                    -- The placeholder one-sentence body that ships in the README until it's fleshed out. Lets us hand-maintain READMEs while keeping the rulebook authoritative for the seed content.
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS readme_length NUMERIC;                       -- Best-known character count of the README file on disk. Populated by a tooling pass; null means 'not yet measured'. Used to compute IsReadmeStub.
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS related_axiom_id TEXT;                       -- FK to OntologyAxioms.AxiomId — the axiom this feature operationalizes (if any)
ALTER TABLE platform_features ADD COLUMN IF NOT EXISTS status TEXT;                                 -- shipped | partial | planned — current implementation status
COMMENT ON TABLE platform_features IS 'The catalog of distinctive features the ERB platform offers. The rulebook is the formal SSoT for this list; the repo''s README and per-feature README files MUST conform to these rows. Each feature has a one-line summary (the elevator pitch), a Tier (headline vs additional), a Priority (sort order within tier), and a ReadmeFilePath (where the long-form explanation lives — even if it''s still a stub). IsReadmeStub is calculated so ''which READMEs are still missing'' is a queryable fact, not a tribal one. Many features reference an OntologyAxiom — that''s the axiom the feature operationalizes.';
COMMENT ON COLUMN platform_features.feature_id IS 'Stable PK, e.g. feature-001';
COMMENT ON COLUMN platform_features.name IS 'Full feature name as it appears in headings';
COMMENT ON COLUMN platform_features.short_name IS 'Short identifier for cross-references (e.g. ''ADP'', ''Hub-and-Spoke'')';
COMMENT ON COLUMN platform_features.tier IS 'headline | additional — drives the two README sections';
COMMENT ON COLUMN platform_features.priority IS 'Sort order within tier (lower = higher up)';
COMMENT ON COLUMN platform_features.one_line_summary IS 'The elevator pitch — one sentence, no clauses about hypotheticals';
COMMENT ON COLUMN platform_features.readme_file_path IS 'Path to the per-feature README, relative to repo root. Hand-maintained but MUST conform to this row.';
COMMENT ON COLUMN platform_features.readme_stub_content IS 'The placeholder one-sentence body that ships in the README until it''s fleshed out. Lets us hand-maintain READMEs while keeping the rulebook authoritative for the seed content.';
COMMENT ON COLUMN platform_features.readme_length IS 'Best-known character count of the README file on disk. Populated by a tooling pass; null means ''not yet measured''. Used to compute IsReadmeStub.';
COMMENT ON COLUMN platform_features.related_axiom_id IS 'FK to OntologyAxioms.AxiomId — the axiom this feature operationalizes (if any)';
COMMENT ON COLUMN platform_features.status IS 'shipped | partial | planned — current implementation status';

