-- LegacyRunnerCapabilities: Succession ledger for rulebook-examples/legacy-runner/, a permanent governed example that is no longer privileged. Each row records which platform surface now owns a capability's role (promote / separate / replace) or that it has none (retire). The runner keeps its copy of every capability; nothing is deleted.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS legacy_runner_capabilities (
  legacy_runner_capability_id         TEXT                 PRIMARY KEY          -- PK.
);
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS title TEXT;                         -- Capability name.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS runner_path TEXT;                   -- Where the capability lives inside legacy-runner/.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS summary TEXT;                       -- What the capability does.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS decision TEXT;                      -- promote | separate | replace | retire.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS destination TEXT;                   -- Who owns the behavior after retirement, or why nothing needs to.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS rationale TEXT;                     -- Why this decision.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS status TEXT;                        -- decided | in-progress | done. done means the successor exists and is wired; the runner keeps its copy regardless.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS dependents TEXT;                    -- Known consumers that must be repointed before removal.
ALTER TABLE legacy_runner_capabilities ADD COLUMN IF NOT EXISTS project TEXT;                       -- FK to ProjectMetadata.
COMMENT ON TABLE legacy_runner_capabilities IS 'Succession ledger for rulebook-examples/legacy-runner/, a permanent governed example that is no longer privileged. Each row records which platform surface now owns a capability''s role (promote / separate / replace) or that it has none (retire). The runner keeps its copy of every capability; nothing is deleted.';
COMMENT ON COLUMN legacy_runner_capabilities.legacy_runner_capability_id IS 'PK.';
COMMENT ON COLUMN legacy_runner_capabilities.title IS 'Capability name.';
COMMENT ON COLUMN legacy_runner_capabilities.runner_path IS 'Where the capability lives inside legacy-runner/.';
COMMENT ON COLUMN legacy_runner_capabilities.summary IS 'What the capability does.';
COMMENT ON COLUMN legacy_runner_capabilities.decision IS 'promote | separate | replace | retire.';
COMMENT ON COLUMN legacy_runner_capabilities.destination IS 'Who owns the behavior after retirement, or why nothing needs to.';
COMMENT ON COLUMN legacy_runner_capabilities.rationale IS 'Why this decision.';
COMMENT ON COLUMN legacy_runner_capabilities.status IS 'decided | in-progress | done. done means the successor exists and is wired; the runner keeps its copy regardless.';
COMMENT ON COLUMN legacy_runner_capabilities.dependents IS 'Known consumers that must be repointed before removal.';
COMMENT ON COLUMN legacy_runner_capabilities.project IS 'FK to ProjectMetadata.';

