ALTER TABLE effort_classes ADD COLUMN IF NOT EXISTS complexity_weight NUMERIC;                      -- Non-zero weight used in effort-weighted rollups (progress-report hard requirement).
ALTER TABLE effort_classes ADD COLUMN IF NOT EXISTS sort_order INTEGER;                             -- Ascending complexity order.
COMMENT ON TABLE effort_classes IS 'Effort/complexity classes for user stories (progress-report contract; the most demanding class must be literally named G3).';
COMMENT ON COLUMN effort_classes.effort_class_id IS 'PK. G1 | G2 | G3 (literal names required by the progress-report tool).';
COMMENT ON COLUMN effort_classes.title IS 'Human label of the class.';
COMMENT ON COLUMN effort_classes.complexity_weight IS 'Non-zero weight used in effort-weighted rollups (progress-report hard requirement).';
COMMENT ON COLUMN effort_classes.sort_order IS 'Ascending complexity order.';

