ALTER TABLE delivery_disciplines ADD COLUMN IF NOT EXISTS share_percent NUMERIC;                    -- Share of total effort. Client-visible rows sum to exactly 100.
ALTER TABLE delivery_disciplines ADD COLUMN IF NOT EXISTS description TEXT;                         -- What work belongs to this discipline.
ALTER TABLE delivery_disciplines ADD COLUMN IF NOT EXISTS client_visible BOOLEAN;                   -- Included in the client-facing 100% split.
ALTER TABLE delivery_disciplines ADD COLUMN IF NOT EXISTS sort_order INTEGER;                       -- Display order.
COMMENT ON TABLE delivery_disciplines IS 'Delivery disciplines splitting programme effort. Client-visible SharePercent must sum to 100 (progress-report hard requirement).';
COMMENT ON COLUMN delivery_disciplines.delivery_discipline_id IS 'PK.';
COMMENT ON COLUMN delivery_disciplines.title IS 'Discipline label.';
COMMENT ON COLUMN delivery_disciplines.share_percent IS 'Share of total effort. Client-visible rows sum to exactly 100.';
COMMENT ON COLUMN delivery_disciplines.description IS 'What work belongs to this discipline.';
COMMENT ON COLUMN delivery_disciplines.client_visible IS 'Included in the client-facing 100% split.';
COMMENT ON COLUMN delivery_disciplines.sort_order IS 'Display order.';

