);
ALTER TABLE erb_feature_categories ADD COLUMN IF NOT EXISTS title TEXT;                             -- Epic title.
ALTER TABLE erb_feature_categories ADD COLUMN IF NOT EXISTS erb_package TEXT;                       -- FK to ERBPackages.
