-- ----------------------------------------------------------------------------
-- ERBFeatures: Individual features of the programme (progress-report contract).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS erb_features (
  erb_feature_id                      TEXT                 PRIMARY KEY          -- PK.
);
ALTER TABLE erb_features ADD COLUMN IF NOT EXISTS title TEXT;                                       -- Feature title.
ALTER TABLE erb_features ADD COLUMN IF NOT EXISTS category TEXT;                                    -- FK to ERBFeatureCategories (the epic).
