-- calc_claude_skills_is_deprecated
-- Field: ClaudeSkills.IsDeprecated
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_claude_skills_is_deprecated(p_skill_id TEXT)
