-- calc_effort_classes_story_count
-- Field: EffortClasses.StoryCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_effort_classes_story_count(p_effort_class_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM user_stories WHERE effort_class = (SELECT NULLIF(effort_class_id, '') FROM effort_classes WHERE effort_class_id = p_effort_class_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_weighted_story_load
-- Field: EffortClasses.WeightedStoryLoad
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_effort_classes_weighted_story_load(p_effort_class_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_effort_classes_story_count(p_effort_class_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT complexity_weight FROM effort_classes WHERE effort_class_id = p_effort_class_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_is_heavy_load
-- Field: EffortClasses.IsHeavyLoad
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_effort_classes_is_heavy_load(p_effort_class_id TEXT)
