  SELECT (CASE WHEN calc_effort_classes_is_heavy_load(p_effort_class_id) THEN ('heavy')::text ELSE ('light')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_class_label
-- Field: EffortClasses.ClassLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_effort_classes_class_label(p_effort_class_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(title, '') FROM effort_classes WHERE effort_class_id = p_effort_class_id), ' (', calc_effort_classes_load_band(p_effort_class_id), ')'))::text;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_name
-- Field: DeliveryDisciplines.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_name(p_delivery_discipline_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(title, '') FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_visible_share
-- Field: DeliveryDisciplines.VisibleShare
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_visible_share(p_delivery_discipline_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE((SELECT client_visible FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), FALSE) THEN ((SELECT share_percent FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_is_major_discipline
-- Field: DeliveryDisciplines.IsMajorDiscipline
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_is_major_discipline(p_delivery_discipline_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((SELECT share_percent FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::NUMERIC >= 20)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_is_visible_major
-- Field: DeliveryDisciplines.IsVisibleMajor
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_is_visible_major(p_delivery_discipline_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT client_visible FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), FALSE) AND calc_delivery_disciplines_is_major_discipline(p_delivery_discipline_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_discipline_tier
-- Field: DeliveryDisciplines.DisciplineTier
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_discipline_tier(p_delivery_discipline_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_delivery_disciplines_is_visible_major(p_delivery_discipline_id) THEN ('major')::text ELSE (CASE WHEN COALESCE((SELECT client_visible FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), FALSE) THEN ('minor')::text ELSE ('internal')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_is_client_headline
-- Field: DeliveryDisciplines.IsClientHeadline
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_is_client_headline(p_delivery_discipline_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_delivery_disciplines_discipline_tier(p_delivery_discipline_id) = 'major')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_discipline_label
-- Field: DeliveryDisciplines.DisciplineLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_discipline_label(p_delivery_discipline_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_delivery_disciplines_is_client_headline(p_delivery_discipline_id) THEN (CONCAT((SELECT NULLIF(title, '') FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), ' *'))::text ELSE ((SELECT NULLIF(title, '') FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::text END)::text;
$$ LANGUAGE sql STABLE;

