    SELECT STRING_AGG(project_slot_witness_id::TEXT, ', ' ORDER BY project_slot_witness_id)
    FROM project_slot_witnesses
    WHERE slot = p_project_layout_slot_id
  );
$$ LANGUAGE sql STABLE;



