-- ----------------------------------------------------------------------------
-- vw_project_metadata: Project overview
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_project_metadata CASCADE;
CREATE VIEW vw_project_metadata WITH (security_invoker = ON) AS
SELECT
  t.project_id,
  t.name,                                                                       -- Effortlessly Invariant Rulesbooks (ERB)
  t.purpose,                                                                    -- Host a catalog of independent Effortless projects (rulebook-examples/<project>/), each a self-contained rulebook that fully captures one domain and selects the subset of platform substrates it needs. The platform proves that a rulebook is a complete spec: given just the rulebook, any frontier LLM can answer any question about the domain or produce a faithful implementation in any language / platform.
  t.architecture,                                                               -- Catalog of N independent Effortless projects under rulebook-examples/. Each project's rulebook JSON is its own hub / durable SSoT, with input spokes (Airtable, LLM edits, admin portal) and a project-chosen subset of the platform's 15 substrates as output spokes. The platform itself is one such project (effortless-platform/) describing ERB.
  t.entry_point,                                                                -- ./start.sh boots the admin portal (web UI) — local dev experience for any rulebook project
  t.portal_url,                                                                 -- http://localhost:7777 — admin portal served by run-web-portal.sh
  t.proxy_url,                                                                  -- http://localhost:4242 — ssotme-proxy serving substrate transpilers as HTTP routes
  t.repository_root,                                                            -- effortlessly-invariant-rulesbooks/
  calc_project_metadata_rulebook_domains(t.project_id) AS rulebook_domains,     -- Reverse relationship: all RulebookDomains rows of this project.
  calc_project_metadata_claude_skills(t.project_id) AS claude_skills,           -- Reverse relationship: all ClaudeSkills rows of this project.
  calc_project_metadata_build_phases(t.project_id) AS build_phases,             -- Reverse relationship: delivery phases of this project.
  calc_project_metadata_erb_packages(t.project_id) AS erb_packages,             -- Reverse relationship: capability packages of this project.
  calc_project_metadata_consistency_rules(t.project_id) AS consistency_rules,   -- Reverse relationship: consistency rules of this project.
  calc_project_metadata_mobile_nav_tabs(t.project_id) AS mobile_nav_tabs,       -- Reverse relationship: mobile tabs of this project.
  calc_project_metadata_domain_count(t.project_id) AS domain_count,             -- Order 1. Number of project containers (RulebookDomains rows) in the repo.
  calc_project_metadata_skill_count(t.project_id) AS skill_count,               -- Order 1. Number of Claude skills in the catalog (including deprecated).
  calc_project_metadata_consistency_rule_count(t.project_id) AS consistency_rule_count,-- Order 1. Number of consistency rules governing the repo.
  calc_project_metadata_phase_count(t.project_id) AS phase_count,               -- Order 1. Number of delivery phases in the programme.
  calc_project_metadata_toy_domain_count(t.project_id) AS toy_domain_count,     -- Order 3. Domains declared toys (Kind = toy).
  calc_project_metadata_deprecated_skill_count(t.project_id) AS deprecated_skill_count,-- Order 2. Deprecated skills still modeled.
  calc_project_metadata_priced_phase_count(t.project_id) AS priced_phase_count, -- Order 2. Phases carrying a quoted price.
  calc_project_metadata_story_total(t.project_id) AS story_total,               -- Order 2. All user stories across phases.
  calc_project_metadata_open_finding_total(t.project_id) AS open_finding_total, -- Order 3. Open consistency findings across every rule.
  calc_project_metadata_isolated_skill_count(t.project_id) AS isolated_skill_count,-- Order 3. Skills with no routing edges.
  calc_project_metadata_done_story_total(t.project_id) AS done_story_total,     -- Order 3. Stories asserted done across all phases.
  calc_project_metadata_toy_share(t.project_id) AS toy_share,                   -- Order 4. Percent of containers that are toys.
  calc_project_metadata_clean_domain_count(t.project_id) AS clean_domain_count, -- Order 4. Domains with zero open findings.
  calc_project_metadata_satisfied_rule_count(t.project_id) AS satisfied_rule_count,-- Order 4. Rules with zero open findings.
  calc_project_metadata_cardless_domain_count(t.project_id) AS cardless_domain_count,-- Order 4. Real projects missing a flavor card.
  calc_project_metadata_weighted_done_total(t.project_id) AS weighted_done_total,-- Order 4. Effort weight earned by done stories across the programme.
  calc_project_metadata_avg_phase_done_percent(t.project_id) AS avg_phase_done_percent,-- Order 4. Mean of per-phase done percentages.
  calc_project_metadata_consistency_percent(t.project_id) AS consistency_percent,-- Order 5. Percent of containers with zero open findings — the headline repo-health number.
  calc_project_metadata_rule_compliance_percent(t.project_id) AS rule_compliance_percent,-- Order 5. Percent of consistency rules fully satisfied.
  calc_project_metadata_shippable_tab_count(t.project_id) AS shippable_tab_count,-- Order 5. Mobile tabs whose every route is built.
  calc_project_metadata_healthy_skill_count(t.project_id) AS healthy_skill_count,-- Order 5. Skill catalog entries that are neither isolated nor deprecated-but-routed.
  calc_project_metadata_programme_progress_percent(t.project_id) AS programme_progress_percent,-- Order 5. Mean effort-weighted done percent across phases.
  calc_project_metadata_is_repo_consistent(t.project_id) AS is_repo_consistent, -- Order 5. Every container is clean — the programme's exit condition.
  calc_project_metadata_project_layout_slots(t.project_id) AS project_layout_slots,-- Reverse relationship: canonical project-shape slots.
  calc_project_metadata_layout_slot_count(t.project_id) AS layout_slot_count,   -- Order 1. Slots in the canonical project shape.
  calc_project_metadata_fully_implemented_count(t.project_id) AS fully_implemented_count,-- Order 5. Governed projects that fill the full implementation contract.
  calc_project_metadata_legacy_runner_capabilities(t.project_id) AS legacy_runner_capabilities,-- Reverse relationship: legacy-runner capabilities inventoried for this project.
  calc_project_metadata_runner_capability_count(t.project_id) AS runner_capability_count,-- Order 1. Legacy-runner capabilities inventoried.
  calc_project_metadata_decided_capability_count(t.project_id) AS decided_capability_count,-- Order 2. Capabilities with a decision and destination.
  calc_project_metadata_resolved_capability_count(t.project_id) AS resolved_capability_count,-- Order 2. Capabilities whose successor exists and is wired.
  calc_project_metadata_is_runner_inventory_complete(t.project_id) AS is_runner_inventory_complete,-- Order 3. Every inventoried capability has a recorded decision and destination (US-051).
  calc_project_metadata_is_runner_succession_complete(t.project_id) AS is_runner_succession_complete-- Order 4. Every capability's successor exists and is wired.
FROM project_metadata t;

-- ----------------------------------------------------------------------------
-- vw_ontology_axioms: Positive-form invariants the project is built on. These are the load-bearing claims; if any one is dropped, the methodology no longer holds. FramingInvariants are mistakes that violate these axioms.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ontology_axioms CASCADE;
CREATE VIEW vw_ontology_axioms WITH (security_invoker = ON) AS
SELECT
  t.axiom_id,
  calc_ontology_axioms_name(t.axiom_id) AS name,                                -- Order 1. Display alias (calculated). Order 1.
  t.short_name,
  t.statement,                                                                  -- The axiom in one sentence
  t.why,                                                                        -- What collapses if you give this up
  t.implication,                                                                -- Concrete consequence for how the project is built / discussed
  t.status,                                                                     -- active | revising | retired
  calc_ontology_axioms_framing_invariants(t.axiom_id) AS framing_invariants,    -- Reverse relationship: FramingInvariants rows whose ViolatedAxiomId points here.
  calc_ontology_axioms_platform_features(t.axiom_id) AS platform_features,      -- Reverse relationship: PlatformFeatures rows whose RelatedAxiomId points here.
  calc_ontology_axioms_invariant_count(t.axiom_id) AS invariant_count,          -- Order 1. Framing invariants that cite this axiom as the one violated.
  calc_ontology_axioms_feature_count(t.axiom_id) AS feature_count,              -- Order 1. Platform features that operationalize this axiom.
  calc_ontology_axioms_is_active(t.axiom_id) AS is_active,                      -- Order 1. The axiom is currently in force.
  calc_ontology_axioms_critical_invariant_count(t.axiom_id) AS critical_invariant_count,-- Order 2. Critical framing invariants protecting this axiom.
  calc_ontology_axioms_shipped_feature_count(t.axiom_id) AS shipped_feature_count,-- Order 2. Shipped features operationalizing this axiom.
  calc_ontology_axioms_is_load_bearing(t.axiom_id) AS is_load_bearing,          -- Order 2. Something in the repo depends on this axiom explicitly.
  calc_ontology_axioms_is_well_guarded(t.axiom_id) AS is_well_guarded,          -- Order 3. Load-bearing and protected by at least one critical framing invariant.
  calc_ontology_axioms_guard_ratio(t.axiom_id) AS guard_ratio,                  -- Order 3. Share of its invariants that are critical.
  calc_ontology_axioms_guard_state(t.axiom_id) AS guard_state,                  -- Order 4. guarded / exposed / dormant.
  calc_ontology_axioms_is_exposed_foundation(t.axiom_id) AS is_exposed_foundation-- Order 5. Load-bearing but unguarded by any critical invariant.
FROM ontology_axioms t;

-- ----------------------------------------------------------------------------
-- vw_framing_invariants: Mistakes-to-avoid catalog. Each row is one wrong framing that has been caught and corrected, paired with the right framing and the axiom it violates. The portal surfaces these so future agents (and humans) can be re-grounded without rediscovering them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_framing_invariants CASCADE;
CREATE VIEW vw_framing_invariants WITH (security_invoker = ON) AS
SELECT
  t.invariant_id,
  t.name,                                                                       -- Short title for grouping / display
  t.category,                                                                   -- substrate-equality | ssot-locality | hub-spoke-topology | category-error | fail-loud | role-confusion | naming | project-catalog | build-semantics | dialect-binding
  t.wrong_framing,                                                              -- The mistake verbatim
  t.correct_framing,                                                            -- The right framing
  t.why,                                                                        -- The reasoning that anchors it
  t.violated_axiom_id,                                                          -- FK to OntologyAxioms.AxiomId — which axiom the wrong framing violates
  t.severity,                                                                   -- critical | important | nuance
  t.example_context,                                                            -- Where this came up — useful so future agents can recognise the situation
  t.status,                                                                     -- active | retired
  calc_framing_invariants_is_critical(t.invariant_id) AS is_critical,           -- Order 1. Severity is critical.
  calc_framing_invariants_critical_flag(t.invariant_id) AS critical_flag,       -- Order 1. 1 when critical, else 0 — rollup carrier for per-axiom critical counts.
  calc_framing_invariants_axiom_short_name(t.invariant_id) AS axiom_short_name, -- Order 1. Short name of the violated axiom.
  calc_framing_invariants_axiom_is_active(t.invariant_id) AS axiom_is_active,   -- Order 2. Whether the violated axiom is still in force.
  calc_framing_invariants_is_active_critical(t.invariant_id) AS is_active_critical,-- Order 2. Critical and currently enforced.
  calc_framing_invariants_is_enforceable(t.invariant_id) AS is_enforceable,     -- Order 3. Active, critical, and its axiom is still in force.
  calc_framing_invariants_axiom_is_load_bearing(t.invariant_id) AS axiom_is_load_bearing,-- Order 3. Whether the violated axiom is load-bearing.
  calc_framing_invariants_enforcement_state(t.invariant_id) AS enforcement_state,-- Order 4. enforced / advisory / orphan.
  calc_framing_invariants_needs_attention(t.invariant_id) AS needs_attention    -- Order 5. Cites an axiom nothing else depends on.
FROM framing_invariants t;

-- ----------------------------------------------------------------------------
-- vw_platform_features: The catalog of distinctive features the ERB platform offers. The rulebook is the formal SSoT for this list; the repo's README and per-feature README files MUST conform to these rows. Each feature has a one-line summary (the elevator pitch), a Tier (headline vs additional), a Priority (sort order within tier), and a ReadmeFilePath (where the long-form explanation lives — even if it's still a stub). IsReadmeStub is calculated so 'which READMEs are still missing' is a queryable fact, not a tribal one. Many features reference an OntologyAxiom — that's the axiom the feature operationalizes.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_platform_features CASCADE;
CREATE VIEW vw_platform_features WITH (security_invoker = ON) AS
SELECT
  t.feature_id,                                                                 -- Stable PK, e.g. feature-001
  t.name,                                                                       -- Full feature name as it appears in headings
  t.short_name,                                                                 -- Short identifier for cross-references (e.g. 'ADP', 'Hub-and-Spoke')
  t.tier,                                                                       -- headline | additional — drives the two README sections
  t.priority,                                                                   -- Sort order within tier (lower = higher up)
  t.one_line_summary,                                                           -- The elevator pitch — one sentence, no clauses about hypotheticals
  t.readme_file_path,                                                           -- Path to the per-feature README, relative to repo root. Hand-maintained but MUST conform to this row.
  t.readme_stub_content,                                                        -- The placeholder one-sentence body that ships in the README until it's fleshed out. Lets us hand-maintain READMEs while keeping the rulebook authoritative for the seed content.
  t.readme_length,                                                              -- Best-known character count of the README file on disk. Populated by a tooling pass; null means 'not yet measured'. Used to compute IsReadmeStub.
  t.related_axiom_id,                                                           -- FK to OntologyAxioms.AxiomId — the axiom this feature operationalizes (if any)
  t.status,                                                                     -- shipped | partial | planned — current implementation status
  calc_platform_features_is_readme_stub(t.feature_id) AS is_readme_stub,        -- Order 1. True if the README is still a placeholder (ReadmeLength null or < 400 chars). Makes missing READMEs a first-class query.
  calc_platform_features_is_headline(t.feature_id) AS is_headline,              -- Order 1. Feature sits in the headline tier.
  calc_platform_features_is_shipped(t.feature_id) AS is_shipped,                -- Order 1. Feature status is shipped.
  calc_platform_features_shipped_flag(t.feature_id) AS shipped_flag,            -- Order 1. 1 when shipped, else 0 — rollup carrier.
  calc_platform_features_axiom_short_name(t.feature_id) AS axiom_short_name,    -- Order 1. Short name of the related axiom.
  calc_platform_features_needs_readme_work(t.feature_id) AS needs_readme_work,  -- Order 2. Shipped but its README is still a stub.
  calc_platform_features_axiom_invariant_count(t.feature_id) AS axiom_invariant_count,-- Order 2. How many framing invariants guard the related axiom.
  calc_platform_features_axiom_is_load_bearing(t.feature_id) AS axiom_is_load_bearing,-- Order 3. Whether the related axiom is load-bearing.
  calc_platform_features_is_headline_gap(t.feature_id) AS is_headline_gap,      -- Order 3. Headline feature whose README still needs work.
  calc_platform_features_doc_state(t.feature_id) AS doc_state,                  -- Order 4. headline-gap / gap / documented / pending.
  calc_platform_features_is_axiom_backed(t.feature_id) AS is_axiom_backed,      -- Order 4. Shipped and tied to a load-bearing axiom.
  calc_platform_features_is_showcase_feature(t.feature_id) AS is_showcase_feature-- Order 5. Shipped, documented and axiom-backed.
FROM platform_features t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_source_spokes: Peer input spokes that can write into effortless-rulebook.json. The rulebook JSON is the durable SSoT; these are interchangeable sources.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_source_spokes CASCADE;
CREATE VIEW vw_rulebook_source_spokes WITH (security_invoker = ON) AS
SELECT
  t.spoke_id,
  t.name,
  t.kind,                                                                       -- airtable | admin-portal | llm-direct | manual-json | reverse-sync
  t.direction,                                                                  -- input (writes into rulebook) | output (reads from rulebook) | bidirectional
  t.required,                                                                   -- False for all input spokes — any one is sufficient, none is required
  t.purpose,
  t.authority,                                                                  -- On conflict, the rulebook JSON wins; spokes are the editors, not the SSoT
  calc_rulebook_source_spokes_is_bidirectional(t.spoke_id) AS is_bidirectional, -- Order 1. Spoke both reads and writes the hub.
  calc_rulebook_source_spokes_is_optional(t.spoke_id) AS is_optional,           -- Order 1. Spoke is optional for a working project.
  calc_rulebook_source_spokes_is_optional_bidirectional(t.spoke_id) AS is_optional_bidirectional,-- Order 2. An optional editing surface that also writes back.
  calc_rulebook_source_spokes_spoke_kind(t.spoke_id) AS spoke_kind,             -- Order 3. editing-surface / required-sync / one-way.
  calc_rulebook_source_spokes_is_advertised_surface(t.spoke_id) AS is_advertised_surface,-- Order 4. Optional editing surface the docs may advertise.
  calc_rulebook_source_spokes_surface_label(t.spoke_id) AS surface_label        -- Order 5. Display label noting optional editing surfaces.
FROM rulebook_source_spokes t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_domains: Customer ontologies: each domain has its own rulebook + substrate generation. Domains form a TREE — ParentDomainId links a more-elaborate domain back to the simpler one it grew out of (e.g. Talisman ADVANCED ← Talisman BASIC). The UI uses this to present related rulebooks as a set rather than a flat list, and to drive 'next step in the progression' navigation.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_domains CASCADE;
CREATE VIEW vw_rulebook_domains WITH (security_invoker = ON) AS
SELECT
  t.domain_id,
  t.area,                                                                       -- Witnessed physical container: root, rulebook-examples, or toy-rulebooks. Classification is derived separately.
  t.kind,                                                                       -- Declared classification: root | toy | example. A toy is a statement of intent (a small teaching rulebook), not a count of files; change this value to re-classify a project. The folder it lives in is witnessed separately as Area.
  t.is_intentional_exception,                                                   -- True only for the two doctrine-sanctioned containers that deliberately carry no rulebook (naked-claude-vs-effortless-claude, volunteer-shift-scheduler-demo).
  calc_rulebook_domains_name(t.domain_id) AS name,                              -- Order 1. Display alias (calculated). Order 1.
  t.domain_name,
  t.relative_path,                                                              -- rulebook-examples/{domain}/ — each domain is a self-contained Effortless project
  t.rulebook_path,                                                              -- Path to effortless-rulebook.json within domain
  t.complexity_level,                                                           -- minimal, moderate, advanced, or philosophical
  t.table_count,
  t.key_features,                                                               -- Comma-separated: string concat, relationships, aggregations, IF logic, meta-ontology, etc.
  t.purpose,
  t.parent_domain_id,                                                           -- FK to RulebookDomains.DomainId — the simpler domain this one was derived from / builds on. Null for root-level demos (independent starting points). Lets the UI present rulebooks as a tree of related domains.
  t.progression_note,                                                           -- One sentence describing what this domain ADDS over its parent — the specific concept the progression is meant to demonstrate at this step.
  calc_rulebook_domains_child_domains(t.domain_id) AS child_domains,            -- Reverse relationship: RulebookDomains rows whose ParentDomainId points here.
  calc_rulebook_domains_demo_narratives(t.domain_id) AS demo_narratives,        -- Reverse relationship: DemoNarratives rows whose RelatedDomainId points here.
  calc_rulebook_domains_flavor_cards(t.domain_id) AS flavor_cards,              -- Reverse relationship: flavor cards describing this domain.
  t.project,                                                                    -- FK to ProjectMetadata — roots this catalog row to the platform row so repo-wide rollups exist on one dashboard record.
  calc_rulebook_domains_consistency_findings(t.domain_id) AS consistency_findings,-- Reverse relationship: findings against this domain.
  calc_rulebook_domains_slug(t.domain_id) AS slug,                              -- Order 1. Directory slug parsed from the slug-keyed DomainId (domain-<slug>).
  calc_rulebook_domains_is_toy(t.domain_id) AS is_toy,                          -- Order 1. Declared as a toy (Kind = toy).
  calc_rulebook_domains_toy_flag(t.domain_id) AS toy_flag,                      -- Order 2. 1 for declared toys — rollup carrier.
  calc_rulebook_domains_has_rulebook(t.domain_id) AS has_rulebook,              -- Order 1. A rulebook file exists for this container.
  calc_rulebook_domains_finding_count(t.domain_id) AS finding_count,            -- Order 1. Consistency findings ever recorded against this domain (any status).
  calc_rulebook_domains_flavor_card_count(t.domain_id) AS flavor_card_count,    -- Order 1. Flavor cards describing this domain.
  calc_rulebook_domains_child_domain_count(t.domain_id) AS child_domain_count,  -- Order 1. Domains that name this one as progression parent.
  calc_rulebook_domains_expected_rulebook_path(t.domain_id) AS expected_rulebook_path,-- Order 2. Where the rulebook should live under the canonical layout.
  calc_rulebook_domains_open_finding_count(t.domain_id) AS open_finding_count,  -- Order 2. Open findings against this domain.
  calc_rulebook_domains_has_flavor_card(t.domain_id) AS has_flavor_card,        -- Order 2. At least one flavor card describes this domain.
  calc_rulebook_domains_is_progression_root(t.domain_id) AS is_progression_root,-- Order 2. Root of a progression tree.
  calc_rulebook_domains_is_standard_layout(t.domain_id) AS is_standard_layout,  -- Order 3. Rulebook sits in effortless-rulebook/ under either accepted filename.
  calc_rulebook_domains_is_fully_consistent(t.domain_id) AS is_fully_consistent,-- Order 3. No open consistency findings.
  calc_rulebook_domains_clean_flag(t.domain_id) AS clean_flag,                  -- Order 3. 1 when fully consistent — rollup carrier.
  calc_rulebook_domains_consistency_grade(t.domain_id) AS consistency_grade,    -- Order 3. clean / minor / major by open findings.
  calc_rulebook_domains_needs_flavor_card(t.domain_id) AS needs_flavor_card,    -- Order 3. Real project with no catalog card.
  calc_rulebook_domains_needs_flavor_flag(t.domain_id) AS needs_flavor_flag,    -- Order 3. 1 when a card is missing — rollup carrier.
  calc_rulebook_domains_layout_flag(t.domain_id) AS layout_flag,                -- Order 4. 1 when the rulebook is at the canonical path — rollup carrier.
  calc_rulebook_domains_conformance_score(t.domain_id) AS conformance_score,    -- Order 4. Consistent + canonical layout + flavor card + rulebook present (0-4).
  calc_rulebook_domains_is_showcase_ready(t.domain_id) AS is_showcase_ready,    -- Order 4. A clean, canonical, non-toy demo fit for the front page.
  calc_rulebook_domains_conformance_band(t.domain_id) AS conformance_band,      -- Order 5. exemplary / acceptable / needs-work.
  calc_rulebook_domains_showcase_flag(t.domain_id) AS showcase_flag,            -- Order 5. 1 when showcase-ready — rollup carrier.
  calc_rulebook_domains_slot_witnesses(t.domain_id) AS slot_witnesses,          -- Reverse relationship: canonical slot witnesses for this project.
  calc_rulebook_domains_slot_witness_count(t.domain_id) AS slot_witness_count,  -- Order 1. Canonical slots scanned for this project.
  calc_rulebook_domains_present_slot_count(t.domain_id) AS present_slot_count,  -- Order 2. Canonical slots this project currently fills.
  calc_rulebook_domains_implementation_gap_count(t.domain_id) AS implementation_gap_count,-- Order 3. Slots absent from a fully implemented root/example contract.
  calc_rulebook_domains_universal_gap_count(t.domain_id) AS universal_gap_count,-- Order 3. Universal project slots currently absent.
  calc_rulebook_domains_slot_coverage_percent(t.domain_id) AS slot_coverage_percent,-- Order 3. Percent of all canonical slots currently filled.
  calc_rulebook_domains_required_slot_count(t.domain_id) AS required_slot_count,-- Order 4. Slots required for this project's physical area.
  calc_rulebook_domains_required_present_count(t.domain_id) AS required_present_count,-- Order 4. Required-here slots currently present.
  calc_rulebook_domains_required_gap_count(t.domain_id) AS required_gap_count,  -- Order 4. Required-here slots currently absent.
  calc_rulebook_domains_is_fully_implemented(t.domain_id) AS is_fully_implemented,-- Order 4. The root/example-complete contract is fully witnessed.
  calc_rulebook_domains_fully_implemented_flag(t.domain_id) AS fully_implemented_flag,-- Order 4. 1 when fully implemented.
  calc_rulebook_domains_required_slot_coverage_percent(t.domain_id) AS required_slot_coverage_percent,-- Order 5. Percent of slots required for this physical area that are present.
  calc_rulebook_domains_expected_area(t.domain_id) AS expected_area,            -- Order 2. Folder implied by the declared Kind.
  calc_rulebook_domains_is_misfiled(t.domain_id) AS is_misfiled,                -- Order 3. The physical folder disagrees with the declared Kind.
  calc_rulebook_domains_readiness_state(t.domain_id) AS readiness_state,        -- Order 5. intentional-exception | root-ready | root-incomplete | toy | example-ready | example-incomplete. Toy/example is declared (Kind); ready/incomplete is witnessed.
  calc_rulebook_domains_launch_profiles(t.domain_id) AS launch_profiles         -- Reverse relationship: explicit launch instructions for this governed row.
FROM rulebook_domains t;

-- ----------------------------------------------------------------------------
-- vw_project_launch_profiles: One explicit launch contract for every governed project or intentional container.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_project_launch_profiles CASCADE;
CREATE VIEW vw_project_launch_profiles WITH (security_invoker = ON) AS
SELECT
  t.project_launch_profile_id,                                                  -- PK: launch-<domain>.
  t.domain,                                                                     -- FK to the governed repository project.
  t.working_directory,                                                          -- Exact repository-relative working directory.
  t.start_command,                                                              -- Exact command a visitor runs from WorkingDirectory.
  t.experience_description,                                                     -- What the launch command starts.
  t.prerequisite_notes,                                                         -- Explicit setup or dependency requirements.
  t.experience_kind,                                                            -- web | editor | rulespeak | rulebook | cli.
  t.is_start_required,                                                          -- False only for intentional non-project containers.
  t.requires_local_url,                                                         -- Whether this experience must expose a localhost URL.
  calc_project_launch_profiles_name(t.project_launch_profile_id) AS name,       -- Order 1. Human display alias.
  calc_project_launch_profiles_local_services(t.project_launch_profile_id) AS local_services,-- Reverse relationship: localhost services started by this profile.
  calc_project_launch_profiles_primary_service_count(t.project_launch_profile_id) AS primary_service_count,-- Order 1. Number of services marked primary.
  calc_project_launch_profiles_service_count(t.project_launch_profile_id) AS service_count,-- Order 1. Number of modeled localhost services.
  calc_project_launch_profiles_has_complete_instructions(t.project_launch_profile_id) AS has_complete_instructions,-- Order 1. Working directory, command, and experience are explicit.
  calc_project_launch_profiles_has_primary_service(t.project_launch_profile_id) AS has_primary_service,-- Order 2. Exactly one local service is primary.
  calc_project_launch_profiles_is_launch_contract_complete(t.project_launch_profile_id) AS is_launch_contract_complete-- Order 3. Instructions are complete and URL-bearing experiences have one primary service.
FROM project_launch_profiles t;

-- ----------------------------------------------------------------------------
-- vw_project_local_services: Explicit localhost services and health endpoints owned by project launch profiles.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_project_local_services CASCADE;
CREATE VIEW vw_project_local_services WITH (security_invoker = ON) AS
SELECT
  t.project_local_service_id,                                                   -- PK: <domain>:<service-role>.
  t.launch_profile,                                                             -- FK to the launch profile that owns this service.
  t.service_role,                                                               -- primary | editor-ui | editor-api.
  t.local_url,                                                                  -- Explicit localhost URL exposed by the service.
  t.health_url,                                                                 -- Explicit localhost URL used to confirm reachability.
  t.sort_order,                                                                 -- Display order within the launch profile.
  t.is_primary_flag,                                                            -- 1 only for the profile's primary visitor experience.
  calc_project_local_services_name(t.project_local_service_id) AS name,         -- Order 1. Human display alias.
  calc_project_local_services_has_health_url(t.project_local_service_id) AS has_health_url,-- Order 1. A health URL is explicitly modeled.
  calc_project_local_services_is_http_service(t.project_local_service_id) AS is_http_service,-- Order 1. The service uses local HTTP.
  calc_project_local_services_is_complete(t.project_local_service_id) AS is_complete-- Order 1. Both launch and health URLs are explicit.
FROM project_local_services t;

-- ----------------------------------------------------------------------------
-- vw_legacy_runner_capabilities: Succession ledger for rulebook-examples/legacy-runner/, a permanent governed example that is no longer privileged. Each row records which platform surface now owns a capability's role (promote / separate / replace) or that it has none (retire). The runner keeps its copy of every capability; nothing is deleted.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_legacy_runner_capabilities CASCADE;
CREATE VIEW vw_legacy_runner_capabilities WITH (security_invoker = ON) AS
SELECT
  t.legacy_runner_capability_id,                                                -- PK.
  calc_legacy_runner_capabilities_name(t.legacy_runner_capability_id) AS name,  -- Order 1. Display alias (calculated).
  t.title,                                                                      -- Capability name.
  t.runner_path,                                                                -- Where the capability lives inside legacy-runner/.
  t.summary,                                                                    -- What the capability does.
  t.decision,                                                                   -- promote | separate | replace | retire.
  t.destination,                                                                -- Who owns the behavior after retirement, or why nothing needs to.
  t.rationale,                                                                  -- Why this decision.
  t.status,                                                                     -- decided | in-progress | done. done means the successor exists and is wired; the runner keeps its copy regardless.
  t.dependents,                                                                 -- Known consumers that must be repointed before removal.
  t.project,                                                                    -- FK to ProjectMetadata.
  calc_legacy_runner_capabilities_is_decided(t.legacy_runner_capability_id) AS is_decided,-- Order 1. A decision and a destination are both recorded.
  calc_legacy_runner_capabilities_decided_flag(t.legacy_runner_capability_id) AS decided_flag,-- Order 1. 1 when decided — rollup carrier.
  calc_legacy_runner_capabilities_is_kept(t.legacy_runner_capability_id) AS is_kept,-- Order 1. The platform still needs the behavior (promote or separate).
  calc_legacy_runner_capabilities_is_resolved(t.legacy_runner_capability_id) AS is_resolved,-- Order 1. The decision has been carried out.
  calc_legacy_runner_capabilities_resolved_flag(t.legacy_runner_capability_id) AS resolved_flag,-- Order 1. 1 when resolved — rollup carrier.
  calc_legacy_runner_capabilities_capability_state(t.legacy_runner_capability_id) AS capability_state,-- Order 2. undecided / decided / resolved.
  calc_legacy_runner_capabilities_capability_label(t.legacy_runner_capability_id) AS capability_label-- Order 1. Display label with decision.
FROM legacy_runner_capabilities t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_flavors: Classification of each demo rulebook under rulebook-examples/. Lets the UI group projects by what they're TEACHING — a tutorial ladder is a different beast from a computation-heavy ontology. Density numbers come from a static analysis of each rulebook (calculated/aggregation/lookup counts).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_flavors CASCADE;
CREATE VIEW vw_rulebook_flavors WITH (security_invoker = ON) AS
SELECT
  t.flavor_id,
  calc_rulebook_flavors_name(t.flavor_id) AS name,                              -- Order 1. Display alias (calculated). Order 1.
  t.sort_order,                                                                 -- Ascending integer; drives default display order in the portal. Lower = shown first. Tutorial-ladder projects sort before demos; demos before meta/graph.
  t.project_slug,                                                               -- Folder under rulebook-examples/ — also the active-domain.txt value
  t.domain,                                                                     -- FK to RulebookDomains — the project directory this flavor card describes.
  t.display_name,
  t.tagline,
  t.logo_path,
  t.flavor,                                                                     -- crud-template | computation-heavy | aggregation-heavy | graph-ontology | meta-rulebook | tutorial-ladder
  t.complexity,                                                                 -- minimal | basic | advanced
  t.entity_count,
  t.calculated_count,                                                           -- Number of calculated fields
  t.aggregation_count,
  t.lookup_count,
  t.learning_focus,                                                             -- What this demo is designed to teach
  t.good_answer_key_for,                                                        -- Substrate(s) this demo makes a particularly good answer-key witness for — when applicable
  calc_rulebook_flavors_flavor_tags(t.flavor_id) AS flavor_tags,                -- Reverse relationship: FlavorTags rows whose Flavor points here.
  calc_rulebook_flavors_derived_field_count(t.flavor_id) AS derived_field_count,-- Order 1. Calculated + aggregation + lookup fields.
  calc_rulebook_flavors_has_domain(t.flavor_id) AS has_domain,                  -- Order 1. Card is linked to an existing project directory.
  calc_rulebook_flavors_tag_count(t.flavor_id) AS tag_count,                    -- Order 1. Tags attached to this card.
  calc_rulebook_flavors_answer_key_target_count(t.flavor_id) AS answer_key_target_count,-- Order 1. Substrates listed as good answer keys.
  calc_rulebook_flavors_domain_area(t.flavor_id) AS domain_area,                -- Order 1. Area of the linked domain.
  calc_rulebook_flavors_derived_ratio(t.flavor_id) AS derived_ratio,            -- Order 2. Derived fields per entity.
  calc_rulebook_flavors_is_tagged(t.flavor_id) AS is_tagged,                    -- Order 2. Card carries at least one tag.
  calc_rulebook_flavors_is_toy_flavor(t.flavor_id) AS is_toy_flavor,            -- Order 2. Linked domain is a toy.
  calc_rulebook_flavors_domain_finding_count(t.flavor_id) AS domain_finding_count,-- Order 2. Findings recorded against the linked domain.
  calc_rulebook_flavors_domain_open_finding_count(t.flavor_id) AS domain_open_finding_count,-- Order 3. Open findings on the linked domain.
  calc_rulebook_flavors_is_dense_derivation(t.flavor_id) AS is_dense_derivation,-- Order 3. At least one derived field per entity.
  calc_rulebook_flavors_is_catalog_complete(t.flavor_id) AS is_catalog_complete,-- Order 3. Linked to a real domain and tagged.
  calc_rulebook_flavors_domain_is_consistent(t.flavor_id) AS domain_is_consistent,-- Order 4. Whether the linked domain has no open findings.
  calc_rulebook_flavors_domain_is_standard_layout(t.flavor_id) AS domain_is_standard_layout,-- Order 4. Whether the linked domain's rulebook is at the canonical path.
  calc_rulebook_flavors_is_showcase_card(t.flavor_id) AS is_showcase_card,      -- Order 4. Complete card whose domain has no open findings.
  calc_rulebook_flavors_is_catalog_ready(t.flavor_id) AS is_catalog_ready,      -- Order 5. Card and domain are both clean — safe to feature.
  calc_rulebook_flavors_domain_conformance_score(t.flavor_id) AS domain_conformance_score-- Order 5. Conformance score of the linked domain.
FROM rulebook_flavors t;

-- ----------------------------------------------------------------------------
-- vw_field_type_taxonomy: Names every field-type the rulebook supports, with intent and example formula shape. Lets the UI explain what makes a calculated field different from a lookup field from an aggregation, instead of just showing a type tag.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_field_type_taxonomy CASCADE;
CREATE VIEW vw_field_type_taxonomy WITH (security_invoker = ON) AS
SELECT
  t.type_id,
  calc_field_type_taxonomy_name(t.type_id) AS name,                             -- Order 1. Display alias (calculated). Order 1.
  t.type_name,                                                                  -- The string that appears in schema[].type
  t.intent,                                                                     -- What this type is FOR — one sentence
  t.example_formula,                                                            -- A representative formula or definition shape
  t.storage_mode,                                                               -- stored | derived-at-read | derived-at-write — where this field's value lives
  t.read_only_in_ui,                                                            -- True if the portal should never let users edit this field's value directly
  t.expressive_tier,                                                            -- Which substrate ExpressiveCompleteness tier is required to faithfully evaluate this — full | partial-formula | partial-aggregation | shape-only
  calc_field_type_taxonomy_is_stored(t.type_id) AS is_stored,                   -- Order 1. Field type is stored in the base table.
  calc_field_type_taxonomy_is_fully_expressive_tier(t.type_id) AS is_fully_expressive_tier,-- Order 1. Field type belongs to the full expressive tier.
  calc_field_type_taxonomy_is_stored_and_editable(t.type_id) AS is_stored_and_editable,-- Order 2. Stored and user-editable in the UI.
  calc_field_type_taxonomy_tier_label(t.type_id) AS tier_label,                 -- Order 3. input / derived-full / derived-partial.
  calc_field_type_taxonomy_is_input_tier(t.type_id) AS is_input_tier,           -- Order 4. User-entered field type.
  calc_field_type_taxonomy_ui_hint(t.type_id) AS ui_hint                        -- Order 5. editable / read-only.
FROM field_type_taxonomy t;

-- ----------------------------------------------------------------------------
-- vw_formula_dialects: Catalog of formula dialects that a rulebook can declare. Per-rulebook formula dialect is headline feature #6: each demo rulebook names which dialect it speaks (in _meta.formulaDialect), and substrates honor that declaration. The platform rulebook does not enumerate which functions a dialect supports — that lives in each demo rulebook's own formula definitions. This catalog only registers the dialects themselves.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_formula_dialects CASCADE;
CREATE VIEW vw_formula_dialects WITH (security_invoker = ON) AS
SELECT
  t.dialect_id,
  t.name,
  t.origin,                                                                     -- Where the dialect's surface syntax comes from (Excel, Airtable, etc.).
  t.field_ref_syntax,                                                           -- How a rulebook formula references another field.
  t.string_concat,                                                              -- How strings are concatenated in this dialect.
  t.case_sensitive,
  t.example_formula,
  t.primary_substrates,                                                         -- Substrates that have the richest support for this dialect.
  t.status,                                                                     -- active | experimental | deprecated
  t.notes,
  calc_formula_dialects_is_active(t.dialect_id) AS is_active,                   -- Order 1. Dialect is active.
  calc_formula_dialects_primary_substrate_count(t.dialect_id) AS primary_substrate_count,-- Order 1. Substrates listed as primary for this dialect.
  calc_formula_dialects_is_active_multi_substrate(t.dialect_id) AS is_active_multi_substrate,-- Order 2. Active dialect spanning several substrates.
  calc_formula_dialects_dialect_role(t.dialect_id) AS dialect_role,             -- Order 3. primary / niche / retired.
  calc_formula_dialects_is_primary_dialect(t.dialect_id) AS is_primary_dialect, -- Order 4. Active dialect spanning several substrates.
  calc_formula_dialects_dialect_label(t.dialect_id) AS dialect_label            -- Order 5. Display label marking the primary dialect.
FROM formula_dialects t;

-- ----------------------------------------------------------------------------
-- vw_demo_narratives: Curated narratives that demonstrate ERB capabilities in motion: substrates 'follow along' as the rulebook changes. Two narrative styles coexist: (1) commit-sequence narratives (legacy) where a single demo rulebook evolves over commits; (2) cross-rulebook narratives (current) where the same demo is observed across DIFFERENT rulebooks side-by-side. Cross-rulebook supersedes commit-sequence because RulebookDomains now form a tree (ParentDomainId) — the progression is data, not git history.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_demo_narratives CASCADE;
CREATE VIEW vw_demo_narratives WITH (security_invoker = ON) AS
SELECT
  t.narrative_id,
  calc_demo_narratives_name(t.narrative_id) AS name,                            -- Order 1. Display alias (calculated). Order 1.
  t."order",                                                                    -- Order within the narrative sequence.
  t.narrative_name,                                                             -- Name of the overall narrative this step belongs to.
  t.step_name,
  t.related_domain_id,                                                          -- FK to RulebookDomains.DomainId, when this step uses a specific demo rulebook.
  t.what_happens,
  t.key_lesson,
  t.observed_cost,                                                              -- Per-substrate cost observation (e.g. 'OWL 10s, English 5min').
  t.narrative_style,                                                            -- commit-sequence (legacy) | cross-rulebook (current) — how the steps are realized at demo time.
  t.status,                                                                     -- active | deprecated. Deprecated narratives are preserved for historical context but should not be used for new demos.
  t.superseded_by,                                                              -- Name of the narrative that supersedes this one. Lossy soft reference: NarrativeName is shared by all step rows of a narrative, so this cannot be a single-row FK without a Narratives header table (future junction candidate).
  calc_demo_narratives_is_deprecated(t.narrative_id) AS is_deprecated,          -- Order 1. Narrative step is deprecated.
  calc_demo_narratives_is_superseded(t.narrative_id) AS is_superseded,          -- Order 1. A successor narrative is named.
  calc_demo_narratives_domain_name(t.narrative_id) AS domain_name,              -- Order 1. Name of the related domain.
  calc_demo_narratives_is_retired(t.narrative_id) AS is_retired,                -- Order 2. Deprecated or superseded.
  calc_demo_narratives_domain_is_toy(t.narrative_id) AS domain_is_toy,          -- Order 2. Whether the related domain is a toy.
  calc_demo_narratives_is_retired_toy_story(t.narrative_id) AS is_retired_toy_story,-- Order 3. Retired narrative about a toy.
  calc_demo_narratives_is_live_story(t.narrative_id) AS is_live_story,          -- Order 3. Current narrative bound to an existing domain.
  calc_demo_narratives_story_state(t.narrative_id) AS story_state,              -- Order 4. live / retired-toy / retired.
  calc_demo_narratives_is_current_story(t.narrative_id) AS is_current_story     -- Order 5. Narrative still tells a current story.
FROM demo_narratives t;

-- ----------------------------------------------------------------------------
-- vw_glossary: Authoritative glossary for the ERB platform. Every term used in orchestration code, docs, the admin portal UI, or rulebook tables appears here EXACTLY ONCE, with a definition AND an ImplementedAs pointer back into this rulebook (or to source files when the implementation is code rather than data). If a term appears in repo prose but has no row here, that's a documentation bug. If a term has a row here but no ImplementedAs target, that's an architecture bug — every concept should be data, code, or a value.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_glossary CASCADE;
CREATE VIEW vw_glossary WITH (security_invoker = ON) AS
SELECT
  t.term_id,
  calc_glossary_name(t.term_id) AS name,                                        -- Order 1. Display alias (calculated). Order 1.
  t.term,                                                                       -- The canonical word/phrase as it appears in code and docs.
  t.category,                                                                   -- concept | role | artifact | phase | substrate | dimension | pattern | tool | location | invariant — what KIND of thing this term refers to.
  t.definition,                                                                 -- One precise sentence. Do not restate the term itself.
  t.implemented_as,                                                             -- Pointer to where this term is realized: 'table:X', 'column:X.Y', 'value:X.Y=Z', 'file:path/to/file', or 'axiom:axiom-id'. The promise is that a reader can follow this pointer and find the concept's actual realization.
  t.aliases,                                                                    -- Comma-separated other names that should resolve to this term. The canonical spelling is in Term; aliases redirect to it.
  t.notes,
  calc_glossary_alias_count(t.term_id) AS alias_count,                          -- Order 1. Number of aliases listed.
  calc_glossary_has_implementation(t.term_id) AS has_implementation,            -- Order 1. Term points at a concrete implementation.
  calc_glossary_implementation_kind(t.term_id) AS implementation_kind,          -- Order 1. Prefix of ImplementedAs before the colon (file, table, script ...); blank when none.
  calc_glossary_is_file_backed(t.term_id) AS is_file_backed,                    -- Order 2. Implemented as a file path.
  calc_glossary_is_rich_term(t.term_id) AS is_rich_term,                        -- Order 2. Has aliases and an implementation pointer.
  calc_glossary_term_quality(t.term_id) AS term_quality,                        -- Order 3. anchored / rich / implemented / definition-only.
  calc_glossary_is_anchored(t.term_id) AS is_anchored,                          -- Order 4. Rich term anchored to a file.
  calc_glossary_glossary_tier(t.term_id) AS glossary_tier                       -- Order 5. tier-1 / tier-2 / tier-3.
FROM glossary t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_tags: Tag catalog for RulebookFlavors. Each tag has a color and emoji so it renders as a visible chip in the portal. Tags are flexible attributes — a flavor can have many tags. Browse/filter the flavors grid by any combination of tags.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_tags CASCADE;
CREATE VIEW vw_rulebook_tags WITH (security_invoker = ON) AS
SELECT
  t.tag_id,                                                                     -- Stable slug identifier, e.g. tag-postgres, tag-tutorial.
  calc_rulebook_tags_name(t.tag_id) AS name,                                    -- Order 1. Display alias (calculated). Order 1.
  t.label,                                                                      -- Short human-readable label shown as the chip text.
  t.category,                                                                   -- source | substrate | purpose | complexity | feature | flavor — groups tags in the filter panel.
  t.color,                                                                      -- Hex color for the chip background, e.g. #18BFFF.
  t.emoji,                                                                      -- Emoji or icon character shown as the leading icon on the chip.
  t.description,                                                                -- One sentence: what this tag means and when to apply it.
  calc_rulebook_tags_flavor_tags(t.tag_id) AS flavor_tags,                      -- Reverse relationship: FlavorTags rows whose Tag points here.
  calc_rulebook_tags_usage_count(t.tag_id) AS usage_count,                      -- Order 1. Flavor cards carrying this tag.
  calc_rulebook_tags_is_source_tag(t.tag_id) AS is_source_tag,                  -- Order 1. Tag describes the rulebook's source spoke.
  calc_rulebook_tags_is_unused(t.tag_id) AS is_unused,                          -- Order 2. No flavor card uses this tag.
  calc_rulebook_tags_unused_flag(t.tag_id) AS unused_flag,                      -- Order 2. 1 when unused — rollup carrier.
  calc_rulebook_tags_tag_health(t.tag_id) AS tag_health,                        -- Order 3. unused / common / rare.
  calc_rulebook_tags_is_retirement_candidate(t.tag_id) AS is_retirement_candidate,-- Order 4. No card uses the tag.
  calc_rulebook_tags_tag_action(t.tag_id) AS tag_action                         -- Order 5. retire / keep.
FROM rulebook_tags t;

-- ----------------------------------------------------------------------------
-- vw_flavor_tags: Junction table linking RulebookFlavors to RulebookTags (many-to-many via junction). A flavor can have any number of tags; a tag can apply to any number of flavors. The portal renders each flavor's tags as colored chip rows in the grid and uses them to drive the filter panel.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_flavor_tags CASCADE;
CREATE VIEW vw_flavor_tags WITH (security_invoker = ON) AS
SELECT
  t.flavor_tag_id,                                                              -- Stable unique ID for this flavor↔tag assignment.
  calc_flavor_tags_name(t.flavor_tag_id) AS name,                               -- Order 1. Display alias (calculated). Order 1.
  t.flavor,                                                                     -- FK to RulebookFlavors.FlavorId.
  t.tag,                                                                        -- FK to RulebookTags.TagId.
  calc_flavor_tags_tag_label(t.flavor_tag_id) AS tag_label,                     -- Order 1. Label of the tag.
  calc_flavor_tags_tag_category(t.flavor_tag_id) AS tag_category,               -- Order 1. Category of the tag.
  calc_flavor_tags_flavor_display_name(t.flavor_tag_id) AS flavor_display_name, -- Order 1. Display name of the flavor card.
  calc_flavor_tags_is_source_tagging(t.flavor_tag_id) AS is_source_tagging,     -- Order 2. Tag records the source spoke.
  calc_flavor_tags_flavor_tag_count(t.flavor_tag_id) AS flavor_tag_count,       -- Order 2. How many tags the card carries in total.
  calc_flavor_tags_is_sole_tag(t.flavor_tag_id) AS is_sole_tag,                 -- Order 3. The only tag on its card.
  calc_flavor_tags_tag_share(t.flavor_tag_id) AS tag_share,                     -- Order 3. Percent of the card's tag weight this tag holds.
  calc_flavor_tags_is_defining_tag(t.flavor_tag_id) AS is_defining_tag,         -- Order 4. Sole tag on the card and it names the source spoke.
  calc_flavor_tags_tag_weight(t.flavor_tag_id) AS tag_weight                    -- Order 5. Defining tags weigh double in card summaries.
FROM flavor_tags t;

-- ----------------------------------------------------------------------------
-- vw_claude_skills: The catalog of Claude Code skills that make up the effortless-skills skill set (repo renamed from effortless-claude). Each skill is a loadable instruction set that pre-teaches Claude everything it needs to work in an ERB project — naming conventions, pipeline mechanics, formula semantics, etc. Skills are the answer to the LLM learning-curve problem: instead of every user teaching Claude from scratch, the learning is encoded once and loaded on demand. LocalMirrorPath is a derived artifact: clone-skills.sh pulls a live copy of each skill from the source repo so the docs/skills/ mirror stays current.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_claude_skills CASCADE;
CREATE VIEW vw_claude_skills WITH (security_invoker = ON) AS
SELECT
  t.skill_id,                                                                   -- Stable PK, e.g. skill-001
  t.name,                                                                       -- Skill directory name, matches the slash command without the leading /
  calc_claude_skills_slash_command(t.skill_id) AS slash_command,                -- Order 1. The slash command users invoke, e.g. /effortless-cmcc
  t.category,                                                                   -- theory | modeling | pipeline | setup | tooling | data | ecosystem | features
  t.load_gate,                                                                  -- When this skill may load: effortless-project (dual-marker gate), explicit-request, evaluative-question, entry-point (may also load to create the marker), or proactive.
  t.is_entry_point,                                                             -- True for skills allowed to load outside a marked Effortless project because their job is to create or manage the tooling itself.
  t.status,                                                                     -- active or deprecated. Deprecated skills remain modeled so the catalog explains what replaced them.
  t.one_line_summary,                                                           -- One sentence describing when to use this skill
  t.audience,                                                                   -- customer | general — who this skill is written for
  calc_claude_skills_local_mirror_path(t.skill_id) AS local_mirror_path,        -- Order 1. Path to the derived local mirror of this skill. Generated by clone-skills.sh; DO NOT EDIT by hand.
  t.clone_url,                                                                  -- Raw GitHub URL from which clone-skills.sh pulls a fresh copy of this skill
  t.highlight_in_readme,                                                        -- True if this skill should appear in the README skills highlights table — the ones most directly relevant to building with this repo
  t.project,                                                                    -- FK to ProjectMetadata — roots this catalog row to the platform row so repo-wide rollups exist on one dashboard record.
  calc_claude_skills_outbound_routes(t.skill_id) AS outbound_routes,            -- Reverse relationship: routes leaving this skill.
  calc_claude_skills_inbound_routes(t.skill_id) AS inbound_routes,              -- Reverse relationship: routes arriving at this skill.
  calc_claude_skills_is_deprecated(t.skill_id) AS is_deprecated,                -- Order 1. Skill is deprecated.
  calc_claude_skills_deprecated_flag(t.skill_id) AS deprecated_flag,            -- Order 1. 1 when deprecated — rollup carrier.
  calc_claude_skills_outbound_route_count(t.skill_id) AS outbound_route_count,  -- Order 1. Routes leaving this skill.
  calc_claude_skills_inbound_route_count(t.skill_id) AS inbound_route_count,    -- Order 1. Routes arriving at this skill.
  calc_claude_skills_is_customer_facing(t.skill_id) AS is_customer_facing,      -- Order 1. Audience is customer.
  calc_claude_skills_is_isolated(t.skill_id) AS is_isolated,                    -- Order 2. No routing edge touches this skill.
  calc_claude_skills_isolated_flag(t.skill_id) AS isolated_flag,                -- Order 2. 1 when isolated — rollup carrier.
  calc_claude_skills_is_hub(t.skill_id) AS is_hub,                              -- Order 2. Routes to five or more skills.
  calc_claude_skills_route_degree(t.skill_id) AS route_degree,                  -- Order 2. Total routing edges.
  calc_claude_skills_skill_role(t.skill_id) AS skill_role,                      -- Order 3. isolated / hub / leaf / source.
  calc_claude_skills_is_live_hub(t.skill_id) AS is_live_hub,                    -- Order 3. Active hub skill.
  calc_claude_skills_is_deprecated_but_routed(t.skill_id) AS is_deprecated_but_routed,-- Order 3. Deprecated yet still wired into the routing graph.
  calc_claude_skills_catalog_state(t.skill_id) AS catalog_state,                -- Order 4. deprecated-routed / hub / role.
  calc_claude_skills_healthy_flag(t.skill_id) AS healthy_flag,                  -- Order 4. 1 when the catalog entry is healthy — rollup carrier.
  calc_claude_skills_needs_catalog_action(t.skill_id) AS needs_catalog_action,  -- Order 5. Isolated or deprecated-but-routed — needs a catalog decision.
  calc_claude_skills_catalog_label(t.skill_id) AS catalog_label                 -- Order 5. Display label with catalog state.
FROM claude_skills t;

-- ----------------------------------------------------------------------------
-- vw_build_phases: Delivery phases of the repo-consistency programme. Contract table for rulebook-to-progress-report. QuotedPrice values are illustrative planning weights, not invoices.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_build_phases CASCADE;
CREATE VIEW vw_build_phases WITH (security_invoker = ON) AS
SELECT
  t.build_phase_id,                                                             -- PK. Slug identity of the phase.
  calc_build_phases_name(t.build_phase_id) AS name,                             -- Order 1. Display alias (calculated). Order 1.
  t.phase_number,                                                               -- Ordinal position of the phase in the programme.
  t.title,                                                                      -- Human title of the phase.
  t.quoted_price,                                                               -- Illustrative planning weight in currency units. Progress-report contract: any phase carrying a price must contain stories that carry criteria.
  t.duration_months,                                                            -- Planned duration in months.
  t.phase_kind,                                                                 -- fixed-price | priced-option. Progress-report mirrors IsInBaseBid/IsFixedPrice from this.
  t.is_current_bid,                                                             -- Exactly one phase carries TRUE (progress-report hard requirement).
  t.summary,                                                                    -- One-paragraph scope of the phase.
  t.project,                                                                    -- FK to ProjectMetadata — roots the phase to the platform dashboard row.
  calc_build_phases_erb_packages(t.build_phase_id) AS erb_packages,             -- Reverse relationship: packages landing primarily in this phase.
  calc_build_phases_user_stories(t.build_phase_id) AS user_stories,             -- Reverse relationship: stories scheduled in this phase.
  calc_build_phases_story_count(t.build_phase_id) AS story_count,               -- Order 1. Stories scheduled in this phase.
  calc_build_phases_package_count(t.build_phase_id) AS package_count,           -- Order 1. Packages landing primarily in this phase.
  calc_build_phases_is_priced(t.build_phase_id) AS is_priced,                   -- Order 1. Phase carries a quoted price.
  calc_build_phases_priced_flag(t.build_phase_id) AS priced_flag,               -- Order 1. 1 when priced — rollup carrier.
  calc_build_phases_is_fixed_price(t.build_phase_id) AS is_fixed_price,         -- Order 1. Phase kind is fixed-price.
  calc_build_phases_done_story_count(t.build_phase_id) AS done_story_count,     -- Order 2. Stories asserted done in this phase.
  calc_build_phases_effort_weight_sum(t.build_phase_id) AS effort_weight_sum,   -- Order 2. Sum of effort weights of the phase's stories.
  calc_build_phases_has_stories(t.build_phase_id) AS has_stories,               -- Order 2. Phase has at least one story.
  calc_build_phases_done_percent(t.build_phase_id) AS done_percent,             -- Order 3. Percent of stories asserted done.
  calc_build_phases_weighted_done_sum(t.build_phase_id) AS weighted_done_sum,   -- Order 3. Effort weight earned by done stories.
  calc_build_phases_is_priced_with_stories(t.build_phase_id) AS is_priced_with_stories,-- Order 3. Priced phase that carries stories (progress-report guard).
  calc_build_phases_weighted_done_percent(t.build_phase_id) AS weighted_done_percent,-- Order 4. Effort-weighted percent of the phase asserted done.
  calc_build_phases_avg_story_progress(t.build_phase_id) AS avg_story_progress, -- Order 4. Mean criteria-derived progress of the phase's stories.
  calc_build_phases_is_contract_safe(t.build_phase_id) AS is_contract_safe,     -- Order 4. Will not trip the progress-report priced-phase refusal.
  calc_build_phases_phase_state(t.build_phase_id) AS phase_state,               -- Order 5. complete / in-progress / bid / planned.
  calc_build_phases_is_report_safe(t.build_phase_id) AS is_report_safe          -- Order 5. Passes every progress-report phase guard.
FROM build_phases t;

-- ----------------------------------------------------------------------------
-- vw_effort_classes: Effort/complexity classes for user stories (progress-report contract; the most demanding class must be literally named G3).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_effort_classes CASCADE;
CREATE VIEW vw_effort_classes WITH (security_invoker = ON) AS
SELECT
  t.effort_class_id,                                                            -- PK. G1 | G2 | G3 (literal names required by the progress-report tool).
  calc_effort_classes_name(t.effort_class_id) AS name,                          -- Order 1. Display alias (calculated). Order 1.
  t.title,                                                                      -- Human label of the class.
  t.complexity_weight,                                                          -- Non-zero weight used in effort-weighted rollups (progress-report hard requirement).
  t.sort_order,                                                                 -- Ascending complexity order.
  calc_effort_classes_user_stories(t.effort_class_id) AS user_stories,          -- Reverse relationship: stories in this effort class.
  calc_effort_classes_story_count(t.effort_class_id) AS story_count,            -- Order 1. Stories in this effort class.
  calc_effort_classes_weighted_story_load(t.effort_class_id) AS weighted_story_load,-- Order 2. Story count times complexity weight.
  calc_effort_classes_is_heavy_load(t.effort_class_id) AS is_heavy_load,        -- Order 3. Weighted load of 20 or more.
  calc_effort_classes_load_band(t.effort_class_id) AS load_band,                -- Order 4. heavy / light.
  calc_effort_classes_class_label(t.effort_class_id) AS class_label             -- Order 5. Display label with load band.
FROM effort_classes t;

-- ----------------------------------------------------------------------------
-- vw_delivery_disciplines: Delivery disciplines splitting programme effort. Client-visible SharePercent must sum to 100 (progress-report hard requirement).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_delivery_disciplines CASCADE;
CREATE VIEW vw_delivery_disciplines WITH (security_invoker = ON) AS
SELECT
  t.delivery_discipline_id,                                                     -- PK.
  calc_delivery_disciplines_name(t.delivery_discipline_id) AS name,             -- Order 1. Display alias (calculated). Order 1.
  t.title,                                                                      -- Discipline label.
  t.share_percent,                                                              -- Share of total effort. Client-visible rows sum to exactly 100.
  t.description,                                                                -- What work belongs to this discipline.
  t.client_visible,                                                             -- Included in the client-facing 100% split.
  t.sort_order,                                                                 -- Display order.
  calc_delivery_disciplines_visible_share(t.delivery_discipline_id) AS visible_share,-- Order 1. SharePercent when client-visible, else 0 (the client split must sum to 100).
  calc_delivery_disciplines_is_major_discipline(t.delivery_discipline_id) AS is_major_discipline,-- Order 1. Discipline takes at least a fifth of effort.
  calc_delivery_disciplines_is_visible_major(t.delivery_discipline_id) AS is_visible_major,-- Order 2. Client-visible and major.
  calc_delivery_disciplines_discipline_tier(t.delivery_discipline_id) AS discipline_tier,-- Order 3. major / minor / internal.
  calc_delivery_disciplines_is_client_headline(t.delivery_discipline_id) AS is_client_headline,-- Order 4. Major client-visible discipline.
  calc_delivery_disciplines_discipline_label(t.delivery_discipline_id) AS discipline_label-- Order 5. Display label starring headline disciplines.
FROM delivery_disciplines t;

-- ----------------------------------------------------------------------------
-- vw_erb_packages: Capability packages of the platform programme (progress-report contract).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_erb_packages CASCADE;
CREATE VIEW vw_erb_packages WITH (security_invoker = ON) AS
SELECT
  t.erb_package_id,                                                             -- PK.
  calc_erb_packages_name(t.erb_package_id) AS name,                             -- Order 1. Display alias (calculated). Order 1.
  t.title,                                                                      -- Package title.
  t.primary_phase,                                                              -- FK to BuildPhases — the phase where the bulk of this package lands.
  t.sort_order,                                                                 -- Display order.
  t.summary,                                                                    -- What the package delivers.
  t.project,                                                                    -- FK to ProjectMetadata.
  calc_erb_packages_erb_feature_categories(t.erb_package_id) AS erb_feature_categories,-- Reverse relationship: epics in this package.
  calc_erb_packages_erb_features(t.erb_package_id) AS erb_features,             -- Reverse relationship: features in this package.
  calc_erb_packages_category_count(t.erb_package_id) AS category_count,         -- Order 1. Epics in this package.
  calc_erb_packages_feature_count(t.erb_package_id) AS feature_count,           -- Order 1. Features in this package.
  calc_erb_packages_phase_title(t.erb_package_id) AS phase_title,               -- Order 1. Title of the primary phase.
  calc_erb_packages_phase_number(t.erb_package_id) AS phase_number,             -- Order 1. Number of the primary phase.
  calc_erb_packages_story_count(t.erb_package_id) AS story_count,               -- Order 2. Stories across the package's features.
  calc_erb_packages_phase_is_priced(t.erb_package_id) AS phase_is_priced,       -- Order 2. Whether the primary phase is priced.
  calc_erb_packages_done_story_count(t.erb_package_id) AS done_story_count,     -- Order 3. Done stories across the package's features.
  calc_erb_packages_is_priced_package(t.erb_package_id) AS is_priced_package,   -- Order 3. Lands in a priced phase and has stories.
  calc_erb_packages_done_percent(t.erb_package_id) AS done_percent,             -- Order 4. Percent of the package's stories asserted done.
  calc_erb_packages_avg_feature_done_percent(t.erb_package_id) AS avg_feature_done_percent,-- Order 4. Mean of feature done percentages.
  calc_erb_packages_is_complete(t.erb_package_id) AS is_complete,               -- Order 5. Every story in the package is done.
  calc_erb_packages_package_state(t.erb_package_id) AS package_state            -- Order 5. complete / in-progress / planned.
FROM erb_packages t;

-- ----------------------------------------------------------------------------
-- vw_erb_feature_categories: Feature categories (epics) of the programme (progress-report contract).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_erb_feature_categories CASCADE;
CREATE VIEW vw_erb_feature_categories WITH (security_invoker = ON) AS
SELECT
  t.erb_feature_category_id,                                                    -- PK.
  calc_erb_feature_categories_name(t.erb_feature_category_id) AS name,          -- Order 1. Display alias (calculated). Order 1.
  t.title,                                                                      -- Epic title.
  t.erb_package,                                                                -- FK to ERBPackages.
  t.sort_order,                                                                 -- Display order.
  t.summary,                                                                    -- Scope of the epic.
  calc_erb_feature_categories_erb_features(t.erb_feature_category_id) AS erb_features,-- Reverse relationship: features in this epic.
  calc_erb_feature_categories_user_stories(t.erb_feature_category_id) AS user_stories,-- Reverse relationship: stories under this epic.
  calc_erb_feature_categories_feature_count(t.erb_feature_category_id) AS feature_count,-- Order 1. Features in this epic.
  calc_erb_feature_categories_story_count(t.erb_feature_category_id) AS story_count,-- Order 1. Stories under this epic.
  calc_erb_feature_categories_package_title(t.erb_feature_category_id) AS package_title,-- Order 1. Title of the owning package.
  calc_erb_feature_categories_has_stories(t.erb_feature_category_id) AS has_stories,-- Order 2. Epic has at least one story.
  calc_erb_feature_categories_package_feature_count(t.erb_feature_category_id) AS package_feature_count,-- Order 2. Features in the owning package.
  calc_erb_feature_categories_feature_done_story_count(t.erb_feature_category_id) AS feature_done_story_count,-- Order 3. Done stories across the epic's features.
  calc_erb_feature_categories_share_of_package_features(t.erb_feature_category_id) AS share_of_package_features,-- Order 3. Percent of the package's features in this epic.
  calc_erb_feature_categories_done_percent(t.erb_feature_category_id) AS done_percent,-- Order 4. Percent of the epic's stories asserted done.
  calc_erb_feature_categories_avg_story_progress(t.erb_feature_category_id) AS avg_story_progress,-- Order 4. Mean criteria-derived progress of the epic's stories.
  calc_erb_feature_categories_epic_state(t.erb_feature_category_id) AS epic_state-- Order 5. complete / in-progress / planned.
FROM erb_feature_categories t;

-- ----------------------------------------------------------------------------
-- vw_erb_features: Individual features of the programme (progress-report contract).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_erb_features CASCADE;
CREATE VIEW vw_erb_features WITH (security_invoker = ON) AS
SELECT
  t.erb_feature_id,                                                             -- PK.
  calc_erb_features_name(t.erb_feature_id) AS name,                             -- Order 1. Display alias (calculated). Order 1.
  t.title,                                                                      -- Feature title.
  t.category,                                                                   -- FK to ERBFeatureCategories (the epic).
  t.erb_package,                                                                -- FK to ERBPackages. Redundant one-hop copy of the epic's package so package rollups stay 1-hop (SDLAF flattening).
  t.summary,                                                                    -- What the feature delivers.
  calc_erb_features_user_stories(t.erb_feature_id) AS user_stories,             -- Reverse relationship: stories delivering this feature.
  calc_erb_features_story_count(t.erb_feature_id) AS story_count,               -- Order 1. Stories delivering this feature.
  calc_erb_features_category_title(t.erb_feature_id) AS category_title,         -- Order 1. Title of the epic.
  calc_erb_features_package_title(t.erb_feature_id) AS package_title,           -- Order 1. Title of the package.
  calc_erb_features_done_story_count(t.erb_feature_id) AS done_story_count,     -- Order 2. Stories asserted done for this feature.
  calc_erb_features_has_stories(t.erb_feature_id) AS has_stories,               -- Order 2. Feature has at least one story.
  calc_erb_features_category_story_count(t.erb_feature_id) AS category_story_count,-- Order 2. Stories under the owning epic.
  calc_erb_features_done_percent(t.erb_feature_id) AS done_percent,             -- Order 3. Percent of stories asserted done.
  calc_erb_features_share_of_epic_stories(t.erb_feature_id) AS share_of_epic_stories,-- Order 3. Percent of the epic's stories in this feature.
  calc_erb_features_avg_story_progress(t.erb_feature_id) AS avg_story_progress, -- Order 4. Mean criteria-derived progress of the feature's stories.
  calc_erb_features_is_complete(t.erb_feature_id) AS is_complete,               -- Order 4. Every story asserted done.
  calc_erb_features_feature_state(t.erb_feature_id) AS feature_state            -- Order 5. complete / in-progress / planned.
FROM erb_features t;

-- ----------------------------------------------------------------------------
-- vw_user_stories: User stories of the repo-consistency programme (progress-report contract).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_user_stories CASCADE;
CREATE VIEW vw_user_stories WITH (security_invoker = ON) AS
SELECT
  t.user_story_id,                                                              -- PK.
  calc_user_stories_name(t.user_story_id) AS name,                              -- Order 1. Display alias (calculated). Order 1.
  t.req_id,                                                                     -- Requirement code shown in the report (US-001 ...).
  t.story_text,                                                                 -- As a <persona>, I want <capability>, so <outcome>.
  t.build_phase,                                                                -- FK to BuildPhases.
  t.epic,                                                                       -- FK to ERBFeatureCategories. Read directly by the report (not inferred via Feature).
  t.feature,                                                                    -- FK to ERBFeatures.
  t.effort_class,                                                               -- FK to EffortClasses (G1/G2/G3).
  t.status,                                                                     -- todo | in-progress | done (asserted by the team).
  t.dev_progress_percent,                                                       -- Asserted developer progress 0-100 (read by the progress-report tool).
  calc_user_stories_acceptance_criteria(t.user_story_id) AS acceptance_criteria,-- Reverse relationship: criteria of this story.
  calc_user_stories_criterion_count(t.user_story_id) AS criterion_count,        -- Order 1. Acceptance criteria attached.
  calc_user_stories_is_done(t.user_story_id) AS is_done,                        -- Order 1. Team asserts the story is done.
  calc_user_stories_done_flag(t.user_story_id) AS done_flag,                    -- Order 1. 1 when done — rollup carrier.
  calc_user_stories_effort_weight(t.user_story_id) AS effort_weight,            -- Order 1. Complexity weight of the effort class.
  calc_user_stories_phase_number(t.user_story_id) AS phase_number,              -- Order 1. Number of the scheduled phase.
  calc_user_stories_feature_title(t.user_story_id) AS feature_title,            -- Order 1. Title of the feature.
  calc_user_stories_met_criterion_count(t.user_story_id) AS met_criterion_count,-- Order 2. Acceptance criteria currently met.
  calc_user_stories_has_criteria(t.user_story_id) AS has_criteria,              -- Order 2. Story carries acceptance criteria.
  calc_user_stories_weighted_done(t.user_story_id) AS weighted_done,            -- Order 2. Effort weight earned if done, else 0.
  calc_user_stories_derived_progress_percent(t.user_story_id) AS derived_progress_percent,-- Order 3. Progress derived from met criteria; falls back to the asserted percent only when a story has no criteria.
  calc_user_stories_is_acceptance_complete(t.user_story_id) AS is_acceptance_complete,-- Order 3. Every criterion is met.
  calc_user_stories_has_status_drift(t.user_story_id) AS has_status_drift,      -- Order 3. Asserted done while criteria remain unmet.
  calc_user_stories_weighted_progress(t.user_story_id) AS weighted_progress,    -- Order 4. Derived progress times effort weight.
  calc_user_stories_progress_state(t.user_story_id) AS progress_state,          -- Order 4. drift / accepted / in-flight / not-started.
  calc_user_stories_priority_band(t.user_story_id) AS priority_band,            -- Order 5. fix-first / continue / queue.
  calc_user_stories_report_label(t.user_story_id) AS report_label               -- Order 5. Display label with progress state.
FROM user_stories t;

-- ----------------------------------------------------------------------------
-- vw_acceptance_criteria: Acceptance criteria per user story (progress-report contract).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_acceptance_criteria CASCADE;
CREATE VIEW vw_acceptance_criteria WITH (security_invoker = ON) AS
SELECT
  t.acceptance_criterion_id,                                                    -- PK.
  calc_acceptance_criteria_name(t.acceptance_criterion_id) AS name,             -- Order 1. Display alias (calculated). Order 1.
  t.user_story,                                                                 -- FK to UserStories.
  t.criterion,                                                                  -- Testable statement that must hold for the story to be accepted.
  t.is_met,                                                                     -- Witnessed: the criterion currently holds.
  calc_acceptance_criteria_met_flag(t.acceptance_criterion_id) AS met_flag,     -- Order 1. 1 when met — rollup carrier.
  calc_acceptance_criteria_story_req_id(t.acceptance_criterion_id) AS story_req_id,-- Order 1. ReqId of the owning story.
  calc_acceptance_criteria_story_status(t.acceptance_criterion_id) AS story_status,-- Order 1. Asserted status of the owning story.
  calc_acceptance_criteria_story_is_done(t.acceptance_criterion_id) AS story_is_done,-- Order 2. Whether the owning story is asserted done.
  calc_acceptance_criteria_story_criterion_count(t.acceptance_criterion_id) AS story_criterion_count,-- Order 2. Sibling criteria count.
  calc_acceptance_criteria_is_inconsistent_with_story(t.acceptance_criterion_id) AS is_inconsistent_with_story,-- Order 3. Story says done but this criterion is not met.
  calc_acceptance_criteria_share_of_story(t.acceptance_criterion_id) AS share_of_story,-- Order 3. Percent of the story this criterion represents.
  calc_acceptance_criteria_story_derived_progress(t.acceptance_criterion_id) AS story_derived_progress,-- Order 4. Criteria-derived progress of the owning story.
  calc_acceptance_criteria_criterion_state(t.acceptance_criterion_id) AS criterion_state,-- Order 4. contradicts-story / met / pending.
  calc_acceptance_criteria_needs_review(t.acceptance_criterion_id) AS needs_review,-- Order 5. Contradicts the story's asserted status.
  calc_acceptance_criteria_story_is_ahead_of_criterion(t.acceptance_criterion_id) AS story_is_ahead_of_criterion-- Order 5. Story is over half done while this criterion is still pending.
FROM acceptance_criteria t;

-- ----------------------------------------------------------------------------
-- vw_consistency_rules: Repo-wide consistency invariants as data. Each row is a checkable rule with a fix playbook; ConsistencyFindings rows are its violations.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_consistency_rules CASCADE;
CREATE VIEW vw_consistency_rules WITH (security_invoker = ON) AS
SELECT
  t.consistency_rule_id,                                                        -- PK.
  calc_consistency_rules_name(t.consistency_rule_id) AS name,                   -- Order 1. Display alias (calculated). Order 1.
  t.rule_code,                                                                  -- Short slug code of the rule.
  t.severity,                                                                   -- critical | major | minor.
  t.scope,                                                                      -- demo (per project directory) | repo (whole repository).
  t.statement,                                                                  -- The invariant in one sentence.
  t.check_mechanism,                                                            -- How the rule is verified (shell/jq sketch or derived-field reference).
  t.fix_playbook,                                                               -- How to bring a violating project into conformance.
  t.source_doctrine,                                                            -- Where the rule is stated (CLAUDE.md section or skill).
  t.is_scanner_derived,                                                         -- True when this rule's findings are re-derived by scripts/scan-project-slots.py; they close by re-running the scan, never by hand.
  t.project,                                                                    -- FK to ProjectMetadata.
  calc_consistency_rules_consistency_findings(t.consistency_rule_id) AS consistency_findings,-- Reverse relationship: findings of this rule.
  calc_consistency_rules_finding_count(t.consistency_rule_id) AS finding_count, -- Order 1. Findings recorded under this rule (any status).
  calc_consistency_rules_is_critical(t.consistency_rule_id) AS is_critical,     -- Order 1. Severity is critical.
  calc_consistency_rules_is_repo_scope(t.consistency_rule_id) AS is_repo_scope, -- Order 1. Rule applies to the repo/platform rather than per demo.
  calc_consistency_rules_open_finding_count(t.consistency_rule_id) AS open_finding_count,-- Order 2. Open findings under this rule.
  calc_consistency_rules_has_findings(t.consistency_rule_id) AS has_findings,   -- Order 2. Rule has ever been violated.
  calc_consistency_rules_is_satisfied(t.consistency_rule_id) AS is_satisfied,   -- Order 3. No open findings under this rule.
  calc_consistency_rules_satisfied_flag(t.consistency_rule_id) AS satisfied_flag,-- Order 3. 1 when satisfied — rollup carrier.
  calc_consistency_rules_accepted_or_fixed_count(t.consistency_rule_id) AS accepted_or_fixed_count,-- Order 3. Findings that are fixed or accepted exceptions.
  calc_consistency_rules_open_critical_flag(t.consistency_rule_id) AS open_critical_flag,-- Order 3. 1 when a critical rule has open findings.
  calc_consistency_rules_rule_state(t.consistency_rule_id) AS rule_state,       -- Order 4. satisfied / critical-open / open.
  calc_consistency_rules_resolution_percent(t.consistency_rule_id) AS resolution_percent,-- Order 4. Percent of findings resolved (fixed or accepted).
  calc_consistency_rules_rule_label(t.consistency_rule_id) AS rule_label,       -- Order 5. Display label with rule state.
  calc_consistency_rules_is_sweep_priority(t.consistency_rule_id) AS is_sweep_priority-- Order 5. Unsatisfied and less than half resolved — sweep here first.
FROM consistency_rules t;

-- ----------------------------------------------------------------------------
-- vw_consistency_findings: Witnessed violations of ConsistencyRules, one row per (domain, rule) occurrence. This is the sweep work queue.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_consistency_findings CASCADE;
CREATE VIEW vw_consistency_findings WITH (security_invoker = ON) AS
SELECT
  t.consistency_finding_id,                                                     -- PK.
  calc_consistency_findings_name(t.consistency_finding_id) AS name,             -- Order 1. Display alias (calculated). Order 1.
  t.rule,                                                                       -- FK to ConsistencyRules.
  t.domain,                                                                     -- FK to RulebookDomains; null for repo-scope findings.
  t.detail,                                                                     -- What exactly was observed.
  t.status,                                                                     -- open | fixed | accepted-exception.
  t.detected_on,                                                                -- ISO date the finding was witnessed.
  calc_consistency_findings_is_open(t.consistency_finding_id) AS is_open,       -- Order 1. Finding is still open.
  calc_consistency_findings_open_flag(t.consistency_finding_id) AS open_flag,   -- Order 1. 1 when open — rollup carrier.
  calc_consistency_findings_is_repo_scope(t.consistency_finding_id) AS is_repo_scope,-- Order 1. Finding is not tied to a single domain.
  calc_consistency_findings_rule_severity(t.consistency_finding_id) AS rule_severity,-- Order 1. Severity of the violated rule.
  calc_consistency_findings_rule_is_scanner_derived(t.consistency_finding_id) AS rule_is_scanner_derived,-- Order 1. Whether the violated rule's findings are scanner-derived.
  calc_consistency_findings_rule_code(t.consistency_finding_id) AS rule_code,   -- Order 1. Code of the violated rule.
  calc_consistency_findings_domain_name(t.consistency_finding_id) AS domain_name,-- Order 1. Name of the domain (blank for repo scope).
  calc_consistency_findings_is_open_critical(t.consistency_finding_id) AS is_open_critical,-- Order 2. Open and critical.
  calc_consistency_findings_is_hand_closable(t.consistency_finding_id) AS is_hand_closable,-- Order 2. Open and not scanner-derived: the work queue may mark it fixed or accepted-exception by hand.
  calc_consistency_findings_domain_finding_count(t.consistency_finding_id) AS domain_finding_count,-- Order 2. Total findings on the same domain.
  calc_consistency_findings_rule_finding_count(t.consistency_finding_id) AS rule_finding_count,-- Order 2. Total findings under the same rule.
  calc_consistency_findings_domain_open_finding_count(t.consistency_finding_id) AS domain_open_finding_count,-- Order 3. Open findings on the same domain.
  calc_consistency_findings_rule_open_finding_count(t.consistency_finding_id) AS rule_open_finding_count,-- Order 3. Open findings under the same rule.
  calc_consistency_findings_is_sole_finding_on_domain(t.consistency_finding_id) AS is_sole_finding_on_domain,-- Order 3. The only finding ever recorded on its domain.
  calc_consistency_findings_is_sole_blocker(t.consistency_finding_id) AS is_sole_blocker,-- Order 4. The one open finding keeping its domain from clean.
  calc_consistency_findings_rule_is_satisfied(t.consistency_finding_id) AS rule_is_satisfied,-- Order 4. Whether the rule is now fully satisfied.
  calc_consistency_findings_domain_grade(t.consistency_finding_id) AS domain_grade,-- Order 4. Consistency grade of the domain.
  calc_consistency_findings_priority(t.consistency_finding_id) AS priority,     -- Order 5. P1 / P2 / P3 / closed.
  calc_consistency_findings_is_last_mile(t.consistency_finding_id) AS is_last_mile-- Order 5. Fixing this one finding makes its domain clean.
FROM consistency_findings t;

-- ----------------------------------------------------------------------------
-- vw_mobile_nav_tabs: Primary navigation groups of the root explorer (app/). Rendered as a top navigation bar at desktop width and a bottom tab bar at phone width; each group roots a MobileRoutes subtree. The table name is historical: there is no separate /m mobile shell.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_mobile_nav_tabs CASCADE;
CREATE VIEW vw_mobile_nav_tabs WITH (security_invoker = ON) AS
SELECT
  t.mobile_nav_tab_id,                                                          -- PK.
  calc_mobile_nav_tabs_name(t.mobile_nav_tab_id) AS name,                       -- Order 1. Display alias (calculated). Order 1.
  t.label,                                                                      -- Tab label.
  t.icon,                                                                       -- Icon name from the lucide icon set.
  t.root_path,                                                                  -- Path of the group's root route.
  t.sort_order,                                                                 -- Left-to-right order in the navigation bar.
  t.purpose,                                                                    -- What the navigation group is for.
  t.project,                                                                    -- FK to ProjectMetadata.
  calc_mobile_nav_tabs_mobile_routes(t.mobile_nav_tab_id) AS mobile_routes,     -- Reverse relationship: routes under this navigation group.
  calc_mobile_nav_tabs_route_count(t.mobile_nav_tab_id) AS route_count,         -- Order 1. Routes under this tab.
  calc_mobile_nav_tabs_unbuilt_route_count(t.mobile_nav_tab_id) AS unbuilt_route_count,-- Order 2. Routes under this tab with no screen yet.
  calc_mobile_nav_tabs_has_routes(t.mobile_nav_tab_id) AS has_routes,           -- Order 2. Tab roots at least one route.
  calc_mobile_nav_tabs_build_coverage_percent(t.mobile_nav_tab_id) AS build_coverage_percent,-- Order 3. Percent of routes backed by an existing screen.
  calc_mobile_nav_tabs_is_plan_only(t.mobile_nav_tab_id) AS is_plan_only,       -- Order 3. Every route is still unbuilt.
  calc_mobile_nav_tabs_is_shippable(t.mobile_nav_tab_id) AS is_shippable,       -- Order 4. Every route has a screen.
  calc_mobile_nav_tabs_shippable_flag(t.mobile_nav_tab_id) AS shippable_flag,   -- Order 4. 1 when shippable — rollup carrier.
  calc_mobile_nav_tabs_tab_state(t.mobile_nav_tab_id) AS tab_state              -- Order 5. shippable / plan-only / partial.
FROM mobile_nav_tabs t;

-- ----------------------------------------------------------------------------
-- vw_mobile_routes: Route surface of the root explorer (PLATFORM-EXPLORER-PLAN.md §3): deep-linkable routes under each navigation group. Screen names the React component (pages/<File>.jsx:<Export> under app/src/) that implements the route and stays blank until it exists, so the derived unbuilt counts are the Phase 3 build backlog.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_mobile_routes: Route surface of the root explorer (PLATFORM-EXPLORER-PLAN.md §3): deep-linkable routes under each navigation group. Screen names the React component (pages/<File>.jsx:<Export> under app/src/) that implements the route and stays blank until it exists, so the derived unbuilt counts are the Phase 3 build backlog.
-- SELF-REFERENTIAL SETTLE: MobileRoutes has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: depth. Drivers: parent_route.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_mobile_routes CASCADE;
CREATE VIEW vw_mobile_routes WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.mobile_route_id, jsonb_build_object(
      'depth', CASE WHEN (SELECT NULLIF(t.path::text,'')) = '/' THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (LENGTH((SELECT NULLIF(t.path::text,'')))) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (LENGTH(REPLACE((SELECT NULLIF(t.path::text,'')), '/', ''))) AS v) __safe_numeric), 0)))::text END
    ))
    FROM mobile_routes t WHERE NULLIF(t.parent_route,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.mobile_route_id, jsonb_build_object(
      'depth', CASE WHEN (SELECT NULLIF(t.path::text,'')) = '/' THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (LENGTH((SELECT NULLIF(t.path::text,'')))) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (LENGTH(REPLACE((SELECT NULLIF(t.path::text,'')), '/', ''))) AS v) __safe_numeric), 0)))::text END
    ))
    FROM mobile_routes t
    WHERE NOT (a.settled ? t.mobile_route_id) AND NOT (NULLIF(t.parent_route,'') IS NULL) AND (NULLIF(t.parent_route,'') IS NULL OR a.settled ? t.parent_route)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM mobile_routes t
    WHERE NOT (a.settled ? t.mobile_route_id) AND NOT (NULLIF(t.parent_route,'') IS NULL) AND (NULLIF(t.parent_route,'') IS NULL OR a.settled ? t.parent_route))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.mobile_route_id,                                                            -- PK.
  calc_mobile_routes_name(t.mobile_route_id) AS name,                           -- Order 1. Display alias (calculated). Order 1.
  t.path,                                                                       -- Route path; :param segments mark detail routes.
  t.title,                                                                      -- Screen title shown in the app bar.
  t.tab,                                                                        -- FK to MobileNavTabs — the navigation group that owns this route.
  t.parent_route,                                                               -- FK to MobileRoutes — the breadcrumb parent; null for a group's root and for sibling lists.
  t.screen,                                                                     -- React component implementing this route, as pages/<File>.jsx:<Export> under app/src/; blank until built.
  t.route_kind,                                                                 -- dashboard | list | detail | action | settings.
  t.sort_order,                                                                 -- Order within the tab.
  t.reads_entities,                                                             -- Comma list of tables the route reads (through vw_ views).
  t.description,                                                                -- What the route shows.
  calc_mobile_routes_child_routes(t.mobile_route_id) AS child_routes,           -- Reverse relationship: routes whose back button returns here.
  (SELECT settled #>> ARRAY[t.mobile_route_id::text, 'depth'] FROM settled)::integer AS depth,-- Order 1. Number of path segments; the root path / is depth 0.
  calc_mobile_routes_is_detail(t.mobile_route_id) AS is_detail,                 -- Order 1. Route carries a :param (detail route).
  calc_mobile_routes_has_screen(t.mobile_route_id) AS has_screen,               -- Order 1. Route is implemented by a React component.
  calc_mobile_routes_unbuilt_flag(t.mobile_route_id) AS unbuilt_flag,           -- Order 1. 1 when no component exists yet — rollup carrier for the Phase 3 backlog.
  calc_mobile_routes_child_route_count(t.mobile_route_id) AS child_route_count, -- Order 1. Routes whose back button returns here.
  calc_mobile_routes_tab_label(t.mobile_route_id) AS tab_label,                 -- Order 1. Label of the owning tab.
  calc_mobile_routes_entity_count(t.mobile_route_id) AS entity_count,           -- Order 1. Number of tables the route reads.
  (SELECT settled #>> ARRAY[NULLIF(t.parent_route,''), 'depth'] FROM settled)::integer AS parent_depth,-- Order 2. Depth of the parent route.
  calc_mobile_routes_is_leaf_route(t.mobile_route_id) AS is_leaf_route,         -- Order 2. No route returns to this one.
  calc_mobile_routes_tab_route_count(t.mobile_route_id) AS tab_route_count,     -- Order 2. Routes in the owning tab.
  calc_mobile_routes_is_depth_consistent(t.mobile_route_id) AS is_depth_consistent,-- Order 3. A route without a parent is at most one segment deep; a child is exactly one segment deeper than its parent.
  calc_mobile_routes_tab_unbuilt_count(t.mobile_route_id) AS tab_unbuilt_count, -- Order 3. Unbuilt routes in the owning tab.
  calc_mobile_routes_share_of_tab(t.mobile_route_id) AS share_of_tab,           -- Order 3. Percent of the tab this route represents.
  calc_mobile_routes_tab_coverage_percent(t.mobile_route_id) AS tab_coverage_percent,-- Order 4. Build coverage of the owning tab.
  calc_mobile_routes_route_state(t.mobile_route_id) AS route_state,             -- Order 4. misparented / built / planned.
  calc_mobile_routes_is_on_shippable_tab(t.mobile_route_id) AS is_on_shippable_tab,-- Order 5. Owning tab is fully built.
  calc_mobile_routes_route_label(t.mobile_route_id) AS route_label              -- Order 5. Display label with route state.
FROM mobile_routes t;

-- ----------------------------------------------------------------------------
-- vw_skill_routes: Directed edges of the skill meta-conversation: which skill routes to which, and why (orchestrator routing table + see-also cross-references).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_skill_routes CASCADE;
CREATE VIEW vw_skill_routes WITH (security_invoker = ON) AS
SELECT
  t.skill_route_id,                                                             -- PK.
  calc_skill_routes_name(t.skill_route_id) AS name,                             -- Order 1. Display alias (calculated). Order 1.
  t.from_skill,                                                                 -- FK to ClaudeSkills — the skill that routes.
  t.to_skill,                                                                   -- FK to ClaudeSkills — the skill routed to.
  t.route_reason,                                                               -- Why the routing exists, as stated in the source skill.
  calc_skill_routes_from_status(t.skill_route_id) AS from_status,               -- Order 1. Status of the routing skill.
  calc_skill_routes_to_status(t.skill_route_id) AS to_status,                   -- Order 1. Status of the routed-to skill.
  calc_skill_routes_is_orchestrator_route(t.skill_route_id) AS is_orchestrator_route,-- Order 1. Edge comes from the orchestrator routing table.
  calc_skill_routes_is_deprecated_target(t.skill_route_id) AS is_deprecated_target,-- Order 2. Routes to a deprecated skill.
  calc_skill_routes_to_inbound_count(t.skill_route_id) AS to_inbound_count,     -- Order 2. Inbound degree of the target skill.
  calc_skill_routes_from_outbound_count(t.skill_route_id) AS from_outbound_count,-- Order 2. Outbound degree of the source skill.
  calc_skill_routes_is_hub_edge(t.skill_route_id) AS is_hub_edge,               -- Order 3. Leaves a hub skill.
  calc_skill_routes_is_into_leaf(t.skill_route_id) AS is_into_leaf,             -- Order 3. The only edge into its target.
  calc_skill_routes_is_stale(t.skill_route_id) AS is_stale,                     -- Order 3. Touches a deprecated skill at either end.
  calc_skill_routes_edge_class(t.skill_route_id) AS edge_class,                 -- Order 4. stale / hub-to-leaf / hub-fanout / peer.
  calc_skill_routes_route_label(t.skill_route_id) AS route_label                -- Order 5. Display label with edge class.
FROM skill_routes t;

-- ----------------------------------------------------------------------------
-- vw_project_layout_slots: The canonical root/example/toy project shape as first-class, scan-witnessed data.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_project_layout_slots CASCADE;
CREATE VIEW vw_project_layout_slots WITH (security_invoker = ON) AS
SELECT
  t.project_layout_slot_id,                                                     -- PK.
  calc_project_layout_slots_name(t.project_layout_slot_id) AS name,             -- Order 1. Human display alias.
  t.title,                                                                      -- Human label of the slot.
  t.kind,                                                                       -- file | directory | executable | manifest | rulebook | rulebook-table | readme-final-section | transpiler | init-db | one-of-directories | start-script-syntax | start-script-restart | start-script-urls | start-script-health.
  t.pattern,                                                                    -- The exact path or manifest condition checked.
  t.required_for_root,                                                          -- The repository root must fill this slot.
  t.required_for_example,                                                       -- A fully implemented example must fill this slot.
  t.required_for_toy,                                                           -- Every governed toy must fill this universal slot.
  t.description,                                                                -- Why the slot exists.
  t.project,                                                                    -- FK to the root ProjectMetadata row.
  calc_project_layout_slots_witnesses(t.project_layout_slot_id) AS witnesses,   -- Reverse relationship: project scans of this slot.
  calc_project_layout_slots_witness_count(t.project_layout_slot_id) AS witness_count,-- Order 1. Projects scanned for this slot.
  calc_project_layout_slots_present_count(t.project_layout_slot_id) AS present_count,-- Order 2. Projects that currently fill this slot.
  calc_project_layout_slots_implementation_gap_count(t.project_layout_slot_id) AS implementation_gap_count,-- Order 3. Projects missing this slot when required for full implementation.
  calc_project_layout_slots_coverage_percent(t.project_layout_slot_id) AS coverage_percent,-- Order 3. Percent of scanned projects that fill this slot.
  calc_project_layout_slots_is_universally_filled(t.project_layout_slot_id) AS is_universally_filled,-- Order 4. Every scanned project fills this slot.
  calc_project_layout_slots_slot_health(t.project_layout_slot_id) AS slot_health,-- Order 4. clean | few-gaps | widespread.
  calc_project_layout_slots_slot_label(t.project_layout_slot_id) AS slot_label  -- Order 5. Display label with current health.
FROM project_layout_slots t;

-- ----------------------------------------------------------------------------
-- vw_project_slot_witnesses: Strict filesystem/manifest witnesses for every governed project x canonical slot. Refresh with scripts/scan-project-slots.py.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_project_slot_witnesses CASCADE;
CREATE VIEW vw_project_slot_witnesses WITH (security_invoker = ON) AS
SELECT
  t.project_slot_witness_id,                                                    -- PK: <domain>:<slot>.
  calc_project_slot_witnesses_name(t.project_slot_witness_id) AS name,          -- Order 1. Display alias.
  t.domain,                                                                     -- FK to the governed project row.
  t.slot,                                                                       -- FK to the canonical layout slot.
  t.is_present,                                                                 -- The strict scan currently passes this slot.
  t.witnessed_path,                                                             -- The matched repository-relative path or transpiler Name.
  t.witnessed_detail,                                                           -- Exact observed success or failure.
  t.witnessed_on,                                                               -- ISO date of the scan.
  calc_project_slot_witnesses_present_flag(t.project_slot_witness_id) AS present_flag,-- Order 1. 1 when present.
  calc_project_slot_witnesses_slot_required_for_root(t.project_slot_witness_id) AS slot_required_for_root,-- Order 1. Whether the slot is required of the repository root.
  calc_project_slot_witnesses_slot_required_for_example(t.project_slot_witness_id) AS slot_required_for_example,-- Order 1. Whether the slot is required for full example implementation.
  calc_project_slot_witnesses_slot_required_for_toy(t.project_slot_witness_id) AS slot_required_for_toy,-- Order 1. Whether the slot is universal for toys.
  calc_project_slot_witnesses_domain_area(t.project_slot_witness_id) AS domain_area,-- Order 1. Physical project area.
  calc_project_slot_witnesses_domain_kind(t.project_slot_witness_id) AS domain_kind,-- Order 1. The declared Kind (root | toy | example) of the witnessed project.
  calc_project_slot_witnesses_domain_is_exception(t.project_slot_witness_id) AS domain_is_exception,-- Order 1. Whether the row is a doctrine-sanctioned non-project container.
  calc_project_slot_witnesses_is_required_here(t.project_slot_witness_id) AS is_required_here,-- Order 2. The slot is required for this row's declared Kind.
  calc_project_slot_witnesses_implementation_gap_flag(t.project_slot_witness_id) AS implementation_gap_flag,-- Order 2. 1 when this absence prevents full implementation.
  calc_project_slot_witnesses_universal_gap_flag(t.project_slot_witness_id) AS universal_gap_flag,-- Order 2. 1 when a universal slot is absent.
  calc_project_slot_witnesses_is_gap(t.project_slot_witness_id) AS is_gap,      -- Order 3. Required here and absent.
  calc_project_slot_witnesses_gap_flag(t.project_slot_witness_id) AS gap_flag,  -- Order 3. 1 when this required-here slot is absent.
  calc_project_slot_witnesses_required_here_flag(t.project_slot_witness_id) AS required_here_flag,-- Order 3. 1 when this slot is required here.
  calc_project_slot_witnesses_required_present_flag(t.project_slot_witness_id) AS required_present_flag,-- Order 3. 1 when a required-here slot is present.
  calc_project_slot_witnesses_witness_state(t.project_slot_witness_id) AS witness_state,-- Order 4. gap | filled | optional-empty.
  calc_project_slot_witnesses_is_blocking_gap(t.project_slot_witness_id) AS is_blocking_gap-- Order 5. A current required-here conformance blocker.
FROM project_slot_witnesses t;

-- ----------------------------------------------------------------------------
-- vw_cmcc_summary: One-line CMCC framing for the platform rulebook itself: what it is, what it generates, and what conformance it claims.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_cmcc_summary CASCADE;
CREATE VIEW vw_cmcc_summary WITH (security_invoker = ON) AS
SELECT
  t.cmcc_summary_id,                                                            -- Primary key (auto-synthesized: CMCCSummary had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Identifier for this narrative entry (single-row tables use 'primary').
  t.description,                                                                -- The full narrative content for this concept.
  calc_cmcc_summary_description_length(t.cmcc_summary_id) AS description_length,-- Order 1. Character length of the narrative text.
  calc_cmcc_summary_is_substantive(t.cmcc_summary_id) AS is_substantive,        -- Order 2. Narrative is at least 200 characters (not a placeholder).
  calc_cmcc_summary_narrative_state(t.cmcc_summary_id) AS narrative_state,      -- Order 3. ready / stub.
  calc_cmcc_summary_is_ready(t.cmcc_summary_id) AS is_ready,                    -- Order 4. Narrative is ready for publication.
  calc_cmcc_summary_section_label(t.cmcc_summary_id) AS section_label           -- Order 5. Display label with readiness.
FROM cmcc_summary t;

-- ----------------------------------------------------------------------------
-- vw_project_goal: The primary goal of the platform: the load-bearing claim the project is built to demonstrate.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_project_goal CASCADE;
CREATE VIEW vw_project_goal WITH (security_invoker = ON) AS
SELECT
  t.project_goal_id,                                                            -- Primary key (auto-synthesized: ProjectGoal had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Identifier for this narrative entry (single-row tables use 'primary').
  t.description,                                                                -- The full narrative content for this concept.
  calc_project_goal_description_length(t.project_goal_id) AS description_length,-- Order 1. Character length of the narrative text.
  calc_project_goal_is_substantive(t.project_goal_id) AS is_substantive,        -- Order 2. Narrative is at least 200 characters (not a placeholder).
  calc_project_goal_narrative_state(t.project_goal_id) AS narrative_state,      -- Order 3. ready / stub.
  calc_project_goal_is_ready(t.project_goal_id) AS is_ready,                    -- Order 4. Narrative is ready for publication.
  calc_project_goal_section_label(t.project_goal_id) AS section_label           -- Order 5. Display label with readiness.
FROM project_goal t;

-- ----------------------------------------------------------------------------
-- vw_architectural_highlight: The architectural pattern that makes the platform work: input spokes write to the rulebook, output spokes read from it, conformance binds them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_architectural_highlight CASCADE;
CREATE VIEW vw_architectural_highlight WITH (security_invoker = ON) AS
SELECT
  t.architectural_highlight_id,                                                 -- Primary key (auto-synthesized: ArchitecturalHighlight had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Identifier for this narrative entry (single-row tables use 'primary').
  t.description,                                                                -- The full narrative content for this concept.
  calc_architectural_highlight_description_length(t.architectural_highlight_id) AS description_length,-- Order 1. Character length of the narrative text.
  calc_architectural_highlight_is_substantive(t.architectural_highlight_id) AS is_substantive,-- Order 2. Narrative is at least 200 characters (not a placeholder).
  calc_architectural_highlight_narrative_state(t.architectural_highlight_id) AS narrative_state,-- Order 3. ready / stub.
  calc_architectural_highlight_is_ready(t.architectural_highlight_id) AS is_ready,-- Order 4. Narrative is ready for publication.
  calc_architectural_highlight_section_label(t.architectural_highlight_id) AS section_label-- Order 5. Display label with readiness.
FROM architectural_highlight t;



